export const mockTest5Data = {
  listening: {"parts":[{"part":"A","title":"Part A - Short Conversations","questions":[{"number":1,"question":"What does the man imply?","transcript":"Woman: I need to turn in my volunteer application, but I don’t know where to get the required form.\nMan: The student center keeps copies at the front desk.","options":{"A":"Get the form at the student center","B":"Ask whether the deadline has changed","C":"Submit the form to the department office","D":"Wait until the form is mailed to her"},"correct_answer":"A","explanation":"This is an advice/suggestion question. The man tells the woman where the form can be found, so he implies that she should ask for it at the student center.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445369/Mock_Test_5_01_nddl6k.mp3"},{"number":2,"question":"What does the woman imply about the man?","transcript":"Man: I got to the lecture just as the professor was introducing the first slide.\nWoman: Then you didn’t miss much.","options":{"A":"He arrived after the lecture had begun","B":"He went to the wrong lecture hall","C":"He had already heard the lecture","D":"He left before the lecture ended"},"correct_answer":"A","explanation":"This is an inference question. The man arrived when the lecture was already starting, so he missed only the very beginning.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445369/Mock_Test_5_02_huqrjv.mp3"},{"number":3,"question":"What does the man mean?","transcript":"Woman: My train leaves in forty minutes, and the station is only ten minutes away.\nMan: Then you shouldn’t have any trouble making it.","options":{"A":"She should check the schedule","B":"She will probably miss the train","C":"She has time to get to the station","D":"She should find another way to travel"},"correct_answer":"C","explanation":"This is a gist question. The man says the woman should not have any trouble, meaning she has enough time to catch the train.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445370/Mock_Test_5_03_obpmtg.mp3"},{"number":4,"question":"What does the woman suggest?","transcript":"Man: I need to drop off this letter at the department office, but it closes at four.\nWoman: You’d better head over there now.","options":{"A":"Make an appointment for tomorrow","B":"Go to the office right away","C":"Call the secretary before going","D":"Leave the letter with the woman"},"correct_answer":"B","explanation":"This is an advice/suggestion question. Since the office closes at four, the woman suggests that the man go there before it closes.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445369/Mock_Test_5_04_tepaue.mp3"},{"number":5,"question":"What does the woman imply?","transcript":"Man: Have you seen the photography exhibit downtown?\nWoman: Yes, and I’d go again if I had time.","options":{"A":"The exhibit is difficult to find","B":"The museum is usually crowded","C":"The exhibit is worth visiting","D":"The museum has changed its hours"},"correct_answer":"C","explanation":"This is an inference question. The woman says she would visit the exhibit again, which implies that she thinks it is worth seeing.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444565/Mock_Test_5_05_zpunje.mp3"},{"number":6,"question":"What does the woman imply?","transcript":"Man: The tracking notice says my package was delivered, but it isn’t outside my door.\nWoman: Sometimes packages are left at the apartment office.","options":{"A":"The man should contact the bookstore","B":"The package was delivered to the wrong city","C":"The package may be at the apartment office","D":"The woman received the man’s package"},"correct_answer":"C","explanation":"This is an inference question. The woman suggests a likely place where the package may have been left.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444602/Mock_Test_5_06_c4nz9e.mp3"},{"number":7,"question":"What does the man suggest the woman do?","transcript":"Woman: I was absent when the instructor explained how to format the lab report.\nMan: She usually doesn’t mind answering questions after class.","options":{"A":"Ask the instructor for clarification","B":"Copy another student’s report format","C":"Take the course another semester","D":"Review the lab instructions online"},"correct_answer":"A","explanation":"This is an advice/suggestion question. The man says the instructor answers questions after class, so he suggests that the woman talk to her instructor.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445369/Mock_Test_5_07_twt14j.mp3"},{"number":8,"question":"What does the man mean?","transcript":"Woman: Are you still going on the geology field trip this weekend?\nMan: I wish I could, but my cousin’s wedding is the same day.","options":{"A":"He has already been on the trip","B":"He is unable to attend the trip","C":"He does not know about the trip","D":"He is not interested in geology"},"correct_answer":"B","explanation":"This is a gist question. The man says he wishes he could go, but he has another event, so he will not be able to go on the trip.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444485/Mock_Test_5_08_vivkkb.mp3"},{"number":9,"question":"What does the woman imply?","transcript":"Man: The bookstore is out of the sociology text, and I need it for tomorrow.\nWoman: I bought mine last semester. Let me see if I still have it.","options":{"A":"She will go to the bookstore with him","B":"She bought the wrong textbook","C":"She might still have the textbook","D":"She needs the textbook tomorrow"},"correct_answer":"C","explanation":"This is a prediction question. The woman says she may still have the book, so she may be able to lend it to the man.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444552/Mock_Test_5_09_cmawzx.mp3"},{"number":10,"question":"What does the woman suggest the man do?","transcript":"Man: I’d like to try out for the basketball team, but I’m not sure when practice starts.\nWoman: Coach Miller posted the schedule outside his office.","options":{"A":"Check the coach’s office","B":"Practice with another team","C":"Wait until practice begins","D":"Ask another student to try out"},"correct_answer":"A","explanation":"This is an advice/suggestion question. Since the schedule is outside the coach’s office, the woman suggests that the man check with or go to the coach.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444552/Mock_Test_5_10_nzwrpo.mp3"},{"number":11,"question":"What does the man imply?","transcript":"Woman: I bought this lamp yesterday, but it doesn’t work. I already threw away the receipt.\nMan: The store might still let you exchange it if the price tag is on the box.","options":{"A":"The woman should buy another lamp","B":"The receipt is probably in the box","C":"The lamp may still be exchanged","D":"The store does not accept returns"},"correct_answer":"C","explanation":"This is an inference question. The man says the store might allow an exchange without the receipt if the price tag is still there.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444552/Mock_Test_5_11_ryd2wo.mp3"},{"number":12,"question":"What does the woman suggest?","transcript":"Man: I need to see a doctor, but I’m not sure whether the clinic takes walk-ins.\nWoman: It wouldn’t hurt to phone them before you go.","options":{"A":"Visit the clinic immediately","B":"Call the clinic before going","C":"Make an appointment next week","D":"Ask the doctor about walk-ins"},"correct_answer":"B","explanation":"This is an advice/suggestion question. The phrase “It wouldn’t hurt” means it would be a good idea, so the woman suggests calling the clinic first.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444428/Mock_Test_5_12_ov18bi.mp3"},{"number":13,"question":"What does the man suggest?","transcript":"Woman: I can’t concentrate in my dorm room because the students next door play music every night.\nMan: You might ask the housing office whether another room is available.","options":{"A":"Study in another dormitory","B":"Speak with the housing office","C":"Ask the students to turn off the music","D":"Move her desk away from the wall"},"correct_answer":"B","explanation":"This is an advice/suggestion question. The man suggests asking the housing office about another room, so the woman should ask to change rooms.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444428/Mock_Test_5_13_eq1uow.mp3"},{"number":14,"question":"What does the woman imply?","transcript":"Man: I left my backpack somewhere, and my notebook for history is in it.\nWoman: Did you check the lost-and-found desk in the student union?","options":{"A":"Ask the professor for help","B":"Look in the student union","C":"Return to the library","D":"Buy another notebook"},"correct_answer":"B","explanation":"This is an advice/suggestion question. The woman asks whether he checked the lost-and-found desk, implying that he should check there.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444449/Mock_Test_5_14_affkf3.mp3"},{"number":15,"question":"What does the woman imply?","transcript":"Man: I’m writing my paper on music in the twentieth century.\nWoman: That sounds like a lot to cover in five pages.","options":{"A":"Discuss the topic with the professor","B":"Add more examples to the paper","C":"Choose a more limited topic","D":"Write about a different century"},"correct_answer":"C","explanation":"This is an inference question. The woman says the topic sounds too large for a short paper, implying that the man should narrow it.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444427/Mock_Test_5_15_yo262l.mp3"},{"number":16,"question":"What does the woman suggest?","transcript":"Man: The study room on the second floor is full again.\nWoman: There are usually empty tables in the basement.","options":{"A":"Study somewhere else","B":"Reserve the room later","C":"Wait until a table is free","D":"Ask someone to leave"},"correct_answer":"A","explanation":"This is an advice/suggestion question. The woman mentions another place with tables, so she suggests that the man study somewhere else.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444427/Mock_Test_5_16_ywhijy.mp3"},{"number":17,"question":"What does the woman mean?","transcript":"Man: What did you think of the guest speaker in economics class?\nWoman: I wouldn’t know. I had to leave before she arrived.","options":{"A":"She disagreed with the speaker","B":"She did not hear the speaker","C":"She arrived after the talk began","D":"She thought the talk was interesting"},"correct_answer":"B","explanation":"This is a gist question. The woman says she left before the speaker arrived, so she missed the talk.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444428/Mock_Test_5_17_tevg0z.mp3"},{"number":18,"question":"What does the woman imply?","transcript":"Man: The scholarship application isn’t due until next Friday.\nWoman: True, but Professor Grant still needs time to write your recommendation.","options":{"A":"Begin the application process soon","B":"Ask for a different recommendation","C":"Apply for another scholarship","D":"Wait until next Friday to apply"},"correct_answer":"A","explanation":"This is an advice/suggestion question. The woman warns that the recommendation will take time, implying that the man should send or prepare the application soon.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444427/Mock_Test_5_18_zdmu4i.mp3"},{"number":19,"question":"What does the woman imply?","transcript":"Man: I’m trying to find the latest issue of Science Weekly.\nWoman: The current magazines are on the rack beside the information desk.","options":{"A":"She thinks the issue is not current","B":"She has already read the magazine","C":"She knows where the magazine is","D":"She will help the man find the desk"},"correct_answer":"C","explanation":"This is an inference question. The woman gives the exact location of the current magazines, so she knows where the magazine is located.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444427/Mock_Test_5_19_usefds.mp3"},{"number":20,"question":"What does the woman suggest?","transcript":"Man: I finished my engineering project, but I’m not sure my calculations are correct.\nWoman: Why not have someone in your study group look them over?","options":{"A":"Turn in the project immediately","B":"Have another student check the work","C":"Change the project calculations","D":"Ask for more time to finish"},"correct_answer":"B","explanation":"This is an advice/suggestion question. The woman suggests having someone review the calculations, so the man should ask someone to check his work.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444427/Mock_Test_5_20_s3uxjl.mp3"},{"number":21,"question":"What does the man mean?","transcript":"Woman: I’m driving to the gym at noon. Do you think I’ll find a parking space?\nMan: At that hour? You’d probably have better luck walking.","options":{"A":"She may have trouble finding parking","B":"She should park near the gym","C":"She should go to the gym later","D":"She will probably find a space"},"correct_answer":"A","explanation":"This is an inference question. The man implies that parking will be difficult at noon, so the woman should not drive.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444427/Mock_Test_5_21_ktcxft.mp3"},{"number":22,"question":"What does the man imply?","transcript":"Woman: Our biology class is meeting in the greenhouse today instead of the classroom.\nMan: Great. I was hoping we’d get to see the plants we’ve been reading about.","options":{"A":"He has not done the reading","B":"He forgot where the class meets","C":"He is pleased about the change","D":"He prefers the regular classroom"},"correct_answer":"C","explanation":"This is an attitude question. The man says “Great” and explains that he wanted to see the plants, so he thinks class will be interesting.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444395/Mock_Test_5_22_rlccbq.mp3"},{"number":23,"question":"What does the man imply?","transcript":"Woman: This schedule says the writing workshop starts at three.\nMan: That was last semester’s schedule. The new one says it starts at two.","options":{"A":"The workshop begins at three","B":"The woman has the wrong schedule","C":"The workshop was held last semester","D":"The woman should not attend the workshop"},"correct_answer":"B","explanation":"This is an inference question. The man says the woman is using last semester’s schedule, so she is looking at an old schedule.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444427/Mock_Test_5_23_wfugcb.mp3"},{"number":24,"question":"What does the man imply?","transcript":"Woman: Do you want to get lunch at the new dining hall?\nMan: Sure, as long as the line isn’t out the door again.","options":{"A":"He wants to wait near the door","B":"He has already eaten lunch","C":"He does not like the dining hall","D":"He will go if the line is not too long"},"correct_answer":"D","explanation":"This is an inference question. The man is willing to go only if the line is not too long, implying that he may want to eat elsewhere if it is crowded.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444426/Mock_Test_5_24_aqmstl.mp3"},{"number":25,"question":"What does the man suggest?","transcript":"Woman: My speech for class is almost twelve minutes, but it’s supposed to be eight.\nMan: Maybe you can leave out one of the examples.","options":{"A":"Speak more clearly during the speech","B":"Reduce the length of the speech","C":"Choose a better example","D":"Practice the speech again"},"correct_answer":"B","explanation":"This is an advice/suggestion question. The man suggests removing an example, which would make the speech shorter.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444384/Mock_Test_5_25_ehwnuu.mp3"},{"number":26,"question":"What does the woman imply?","transcript":"Man: I’ve called my roommate three times, but he hasn’t picked up.\nWoman: He was studying until two in the morning.","options":{"A":"His roommate may still be asleep","B":"His roommate is probably studying","C":"His roommate left his phone off campus","D":"His roommate does not want to talk"},"correct_answer":"A","explanation":"This is an inference question. Since the roommate studied very late, the woman implies that he is probably still asleep.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444382/Mock_Test_5_26_ivotod.mp3"},{"number":27,"question":"What does the man suggest?","transcript":"Woman: I got a letter saying there’s a mistake on my tuition bill.\nMan: The financial aid office handles billing corrections.","options":{"A":"Go to the financial aid office","B":"Pay the bill before the deadline","C":"Ask her parents about the mistake","D":"Wait for another letter"},"correct_answer":"A","explanation":"This is an advice/suggestion question. The man says the financial aid office handles such problems, so the woman should go there.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444382/Mock_Test_5_27_dbiufk.mp3"},{"number":28,"question":"What does the woman mean?","transcript":"Man: I’m thinking of taking the shortcut through the construction area.\nWoman: I wouldn’t. They’ve blocked off most of the path.","options":{"A":"Avoid the shortcut","B":"Ride through the gate","C":"Leave earlier than usual","D":"Walk with the woman"},"correct_answer":"A","explanation":"This is an advice/suggestion question. The woman says she would not take the shortcut because the path is blocked.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444382/Mock_Test_5_28_ec2wv3.mp3"},{"number":29,"question":"What does the woman imply?","transcript":"Man: I wrote an article for the campus newspaper, but I’m not sure it’s good enough.\nWoman: You won’t know unless you let the editor read it.","options":{"A":"Write a different article","B":"Show the article to the editor","C":"Read the newspaper first","D":"Ask the editor for a topic"},"correct_answer":"B","explanation":"This is an advice/suggestion question. The woman says the editor should read the article, implying that the man should submit it.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444382/Mock_Test_5_29_ebthuo.mp3"},{"number":30,"question":"What does the man suggest?","transcript":"Woman: I reserved a room for the club meeting, but we need to show a video.\nMan: You might want to make sure the room has a projector.","options":{"A":"Find out whether the room has a projector","B":"Reserve a larger room","C":"Show the video at another meeting","D":"Ask fewer people to attend"},"correct_answer":"A","explanation":"This is an advice/suggestion question. The man says the woman should make sure the room has a projector, so she should check whether the room has the needed equipment.\nBelow is Practice Set 5 — Part B, with Questions 31–38, two extended campus conversations, TOEFL ITP-style options, scripts, answers, and explanations. I followed the Part B format and question-type rules from your design guide, and kept the topics different from Practice 4.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794444382/Mock_Test_5_30_mk5nkk.mp3"}]},{"part":"B","title":"Part B - Extended Conversations","recordings":[{"id":"B1","title":"Part B - Conversation 1","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445376/Mock_Test_5_31-34_clkmdy.mp3","transcript":"Narrator: Listen to a conversation between a student and an academic advisor.Advisor: Good morning. How can I help you?\nStudent: Hi. I’m taking Biology 102, and I wanted to ask about switching my laboratory section.\nAdvisor: All right. Is there a problem with the section you’re in now?\nStudent: Not with the instructor or the class itself. The problem is that my work schedule changed. I’m supposed to work on Tuesday afternoons now, and that’s exactly when my lab meets.\nAdvisor: I see. Which section are you hoping to move into?\nStudent: The Thursday morning section. It would fit my schedule much better.\nAdvisor: Let me check. Hmm. That section is currently full.\nStudent: Oh. So there’s no way to switch?\nAdvisor: Not immediately. But students sometimes change their schedules during the first two weeks. You should keep checking the registration system to see whether a seat opens.\nStudent: Would I need the instructor’s permission if a seat becomes available?\nAdvisor: Usually, no. If the system shows an open seat, you can make the change yourself. But until then, you should continue attending your current section so you don’t miss any lab work.\nStudent: That makes sense. I’ll keep checking online and stay in my Tuesday lab for now.\nAdvisor: Good idea. And if your work schedule becomes a serious conflict, come back and we can discuss other options."},{"id":"B2","title":"Part B - Conversation 2","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445372/Mock_Test_5_35-38_ilcmet.mp3","transcript":"Narrator: Listen to a conversation between a student and a librarian.Librarian: Can I help you find something?\nStudent: Yes, I’m working on a paper for my sociology class, and I need articles about how part-time jobs affect college students.\nLibrarian: Have you tried searching one of the library databases?\nStudent: I did, but I got hundreds of results. Most of them don’t seem very useful.\nLibrarian: What search terms did you use?\nStudent: I typed in “students and jobs.”\nLibrarian: That may be too general. Try using more specific terms, such as “college students,” “part-time employment,” and “academic performance.”\nStudent: So using more exact words will give me better results?\nLibrarian: It should. You can also use the database filters. For example, you can limit your results to scholarly journals or to articles published in the last five years.\nStudent: That would help. My professor said we need at least three recent academic sources.\nLibrarian: Then the scholarly journal filter will be useful. Once you find a good article, look at the subject terms listed with it. Those can help you find similar articles.\nStudent: Great. I’ll try the search again with those terms and filters.\nLibrarian: And if you still get too many results, come back and we can narrow the search further."}],"questions":[{"number":31,"recording_id":"B1","question":"Why does the student visit the advisor?","options":{"A":"To ask about changing her laboratory section","B":"To get permission to miss a biology lecture","C":"To find out why her grade was lowered","D":"To request help choosing a research partner"},"correct_answer":"A","explanation":"This is a gist question. The student says she is taking Biology 102 and wants to ask about switching her laboratory section because her work schedule has changed.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445376/Mock_Test_5_31-34_clkmdy.mp3"},{"number":32,"recording_id":"B1","question":"What problem does the advisor mention?","options":{"A":"The section she wants is already full","B":"The new section meets in another building","C":"The instructor has not approved the change","D":"The laboratory manual has been revised"},"correct_answer":"A","explanation":"This is a detail question. The advisor checks the Thursday morning section and says that it is currently full.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445376/Mock_Test_5_31-34_clkmdy.mp3"},{"number":33,"recording_id":"B1","question":"What does the advisor suggest the student do?","options":{"A":"Speak with the laboratory instructor","B":"Check whether a seat becomes available","C":"Attend both sections for one week","D":"Submit a new course application"},"correct_answer":"B","explanation":"This is an advice/suggestion question. The advisor tells the student to keep checking the registration system because a seat may become available.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445376/Mock_Test_5_31-34_clkmdy.mp3"},{"number":34,"recording_id":"B1","question":"What will the student probably do next?","options":{"A":"She will probably stay in her current section","B":"She will probably drop the biology course","C":"She will probably check the registration system","D":"She will probably ask another student to switch"},"correct_answer":"C","explanation":"This is a prediction question. The student says she will keep checking online and stay in her current Tuesday lab for now.\nRecording 2 — Script\nNarrator: Listen to a conversation between a student and a librarian.\nLibrarian: Can I help you find something?\nStudent: Yes, I’m working on a paper for my sociology class, and I need articles about how part-time jobs affect college students.\nLibrarian: Have you tried searching one of the library databases?\nStudent: I did, but I got hundreds of results. Most of them don’t seem very useful.\nLibrarian: What search terms did you use?\nStudent: I typed in “students and jobs.”\nLibrarian: That may be too general. Try using more specific terms, such as “college students,” “part-time employment,” and “academic performance.”\nStudent: So using more exact words will give me better results?\nLibrarian: It should. You can also use the database filters. For example, you can limit your results to scholarly journals or to articles published in the last five years.\nStudent: That would help. My professor said we need at least three recent academic sources.\nLibrarian: Then the scholarly journal filter will be useful. Once you find a good article, look at the subject terms listed with it. Those can help you find similar articles.\nStudent: Great. I’ll try the search again with those terms and filters.\nLibrarian: And if you still get too many results, come back and we can narrow the search further.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445376/Mock_Test_5_31-34_clkmdy.mp3"},{"number":35,"recording_id":"B2","question":"Why does the student talk to the librarian?","options":{"A":"To arrange a library tour for his class","B":"To ask about finding articles for a paper","C":"To return books that are overdue","D":"To learn how to reserve a study room"},"correct_answer":"B","explanation":"This is a gist question. The student says he is working on a sociology paper and needs help finding useful articles.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445372/Mock_Test_5_35-38_ilcmet.mp3"},{"number":36,"recording_id":"B2","question":"What problem does the librarian identify?","options":{"A":"He is using too many general search terms","B":"He is looking for books instead of articles","C":"He has chosen a topic with few sources","D":"He does not have access to the library website"},"correct_answer":"A","explanation":"This is a detail question. The librarian says that the student’s search terms, “students and jobs,” may be too general.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445372/Mock_Test_5_35-38_ilcmet.mp3"},{"number":37,"recording_id":"B2","question":"What does the librarian say about the database filter?","options":{"A":"It can limit results to scholarly journals","B":"It can automatically write citations","C":"It can show which books are checked out","D":"It can translate articles into English"},"correct_answer":"A","explanation":"This is a detail question. The librarian says the database can limit results to scholarly journals and recent articles.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445372/Mock_Test_5_35-38_ilcmet.mp3"},{"number":38,"recording_id":"B2","question":"What will the student probably do next?","options":{"A":"He will change his research topic","B":"He will meet with his professor","C":"He will search the database again","D":"He will borrow books from another library"},"correct_answer":"C","explanation":"This is a prediction question. The student says he will try the search again using the librarian’s suggested terms and filters.\nCopyable Transcript for ElevenLabs\nRecording 1\nListen to a conversation between a student and an academic advisor.\nGood morning. How can I help you?\nHi. I’m taking Biology 102, and I wanted to ask about switching my laboratory section.\nAll right. Is there a problem with the section you’re in now?\nNot with the instructor or the class itself. The problem is that my work schedule changed. I’m supposed to work on Tuesday afternoons now, and that’s exactly when my lab meets.\nI see. Which section are you hoping to move into?\nThe Thursday morning section. It would fit my schedule much better.\nLet me check. Hmm. That section is currently full.\nOh. So there’s no way to switch?\nNot immediately. But students sometimes change their schedules during the first two weeks. You should keep checking the registration system to see whether a seat opens.\nWould I need the instructor’s permission if a seat becomes available?\nUsually, no. If the system shows an open seat, you can make the change yourself. But until then, you should continue attending your current section so you don’t miss any lab work.\nThat makes sense. I’ll keep checking online and stay in my Tuesday lab for now.\nGood idea. And if your work schedule becomes a serious conflict, come back and we can discuss other options.\nWhy does the student visit the advisor?\nWhat problem does the advisor mention?\nWhat does the advisor suggest the student do?\nWhat will the student probably do next?\nRecording 2\nListen to a conversation between a student and a librarian.\nCan I help you find something?\nYes, I’m working on a paper for my sociology class, and I need articles about how part-time jobs affect college students.\nHave you tried searching one of the library databases?\nI did, but I got hundreds of results. Most of them don’t seem very useful.\nWhat search terms did you use?\nI typed in “students and jobs.”\nThat may be too general. Try using more specific terms, such as “college students,” “part-time employment,” and “academic performance.”\nSo using more exact words will give me better results?\nIt should. You can also use the database filters. For example, you can limit your results to scholarly journals or to articles published in the last five years.\nThat would help. My professor said we need at least three recent academic sources.\nThen the scholarly journal filter will be useful. Once you find a good article, look at the subject terms listed with it. Those can help you find similar articles.\nGreat. I’ll try the search again with those terms and filters.\nAnd if you still get too many results, come back and we can narrow the search further.\nWhy does the student talk to the librarian?\nWhat problem does the librarian identify?\nWhat does the librarian say about the database filter?\nWhat will the student probably do next?\nBelow is Practice Set 5 — Part C, with Questions 39–50, three short academic talks, TOEFL ITP-style options, scripts, answers, explanations, and copyable ElevenLabs transcripts without speaker labels. I kept the format aligned with the TOEFL ITP Listening guide and avoided repeating Practice 4 topics.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445372/Mock_Test_5_35-38_ilcmet.mp3"}]},{"part":"C","title":"Part C - Short Talks","recordings":[{"id":"C1","title":"Part C - Talk 1","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_39-42_n8svgu.mp3","transcript":"Narrator: Listen to a lecture in a biology class.Professor: Today we’re going to discuss one way honeybees communicate with one another. When a worker bee finds a good source of nectar, it does not simply keep that information to itself. It returns to the hive and performs a special movement known as the waggle dance.\nThe waggle dance helps other bees know where food is located. The direction of the dance tells the other bees which way to fly in relation to the sun. The length of the dance gives information about distance. A longer dance usually means the food source is farther away.\nThis behavior is important because a colony has many bees, and they need to gather food efficiently. Instead of every bee searching randomly, successful bees can guide others to flowers that have already been found.\nScientists have studied this dance carefully because it shows that communication in animals does not always depend on sound. In the case of honeybees, movement can carry very specific information."},{"id":"C2","title":"Part C - Talk 2","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_43-46_aduaw8.mp3","transcript":"Narrator: Listen to a lecture in an environmental science class.Professor: Today I want to talk about wetlands. A wetland is an area where water covers the soil, or is present near the surface, for at least part of the year. Wetlands are not exactly lakes, and they are not exactly dry land. They are areas where water and land conditions meet.\nWetlands are important for several reasons. First, they provide habitats for many plants, birds, fish, and insects. Some animals depend on wetlands for nesting or feeding, while others use them during migration.\nWetlands also help improve water quality. As water passes through a wetland, plants and soil can trap some pollutants and extra nutrients. In this way, wetlands act almost like natural filters.\nAnother important function of wetlands is flood control. During heavy rain, wetlands can hold extra water and release it slowly. This does not mean they prevent every flood, but they can reduce the impact of flooding in nearby areas.\nBecause of these benefits, many scientists and communities now work to protect wetlands that were once considered useless land."},{"id":"C3","title":"Part C - Talk 3","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445371/Mock_Test_5_47-50_p3plzj.mp3","transcript":"Narrator: Listen to a talk in an education class.Professor: When many people think of libraries, they picture shelves of books and quiet reading rooms. Those are still part of many libraries, but the role of libraries has changed greatly over time.\nModern libraries often provide much more than printed books. Many offer access to online journals, electronic books, research databases, and digital archives. This is especially useful for students and researchers who need materials that may not be available in printed form.\nLibraries have also become places where people learn practical skills. For example, some libraries offer workshops on using computers, preparing résumés, or finding reliable information online. Others provide meeting rooms, language-learning materials, or programs for children and adults.\nThese changes do not mean that traditional books are no longer important. Instead, libraries have expanded their services. They continue to support reading, but they also help people find, evaluate, and use information in many different forms."}],"questions":[{"number":39,"recording_id":"C1","question":"What is the lecture mainly about?","options":{"A":"How bees find their way back to flowers","B":"How bees communicate the location of food","C":"Why bees are attracted to certain flowers","D":"Why bees live together in large colonies"},"correct_answer":"B","explanation":"This is a gist question. The professor explains how honeybees use the waggle dance to tell other bees where food is located.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_39-42_n8svgu.mp3"},{"number":40,"recording_id":"C1","question":"What information does the waggle dance provide?","options":{"A":"The color of the flowers","B":"The size of the colony","C":"The direction and distance of food","D":"The number of bees near the hive"},"correct_answer":"C","explanation":"This is a detail question. The professor says the dance gives information about the direction and distance of a food source.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_39-42_n8svgu.mp3"},{"number":41,"recording_id":"C1","question":"Why does the professor mention the waggle dance?","options":{"A":"To show that all bees collect the same food","B":"To explain how bees choose a new hive","C":"To give an example of communication by movement","D":"To compare bees with other insects"},"correct_answer":"C","explanation":"This is a purpose question. The professor mentions the waggle dance as an example of how bees communicate through movement.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_39-42_n8svgu.mp3"},{"number":42,"recording_id":"C1","question":"What can be inferred from the lecture?","options":{"A":"Bees depend only on smell to find food","B":"Bees can share information with other bees","C":"Bees usually search for food alone","D":"Bees cannot travel far from the hive"},"correct_answer":"B","explanation":"This is an inference question. The professor explains that bees return to the hive and guide other bees to food, so bees can share information with one another.\nRecording 2 — Script\nNarrator: Listen to a lecture in an environmental science class.\nProfessor: Today I want to talk about wetlands. A wetland is an area where water covers the soil, or is present near the surface, for at least part of the year. Wetlands are not exactly lakes, and they are not exactly dry land. They are areas where water and land conditions meet.\nWetlands are important for several reasons. First, they provide habitats for many plants, birds, fish, and insects. Some animals depend on wetlands for nesting or feeding, while others use them during migration.\nWetlands also help improve water quality. As water passes through a wetland, plants and soil can trap some pollutants and extra nutrients. In this way, wetlands act almost like natural filters.\nAnother important function of wetlands is flood control. During heavy rain, wetlands can hold extra water and release it slowly. This does not mean they prevent every flood, but they can reduce the impact of flooding in nearby areas.\nBecause of these benefits, many scientists and communities now work to protect wetlands that were once considered useless land.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_39-42_n8svgu.mp3"},{"number":43,"recording_id":"C2","question":"What is the lecture mainly about?","options":{"A":"The causes of erosion along rivers","B":"The formation and importance of wetlands","C":"The animals that live in deep oceans","D":"The methods used to build reservoirs"},"correct_answer":"B","explanation":"This is a gist question. The professor defines wetlands and explains several reasons they are important.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_43-46_aduaw8.mp3"},{"number":44,"recording_id":"C2","question":"What does the professor say about wetlands?","options":{"A":"They are always covered by deep water","B":"They are found only near mountains","C":"They contain both water and land features","D":"They are usually too dry for plant life"},"correct_answer":"C","explanation":"This is a detail question. The professor says wetlands are areas where water and land conditions meet.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_43-46_aduaw8.mp3"},{"number":45,"recording_id":"C2","question":"According to the professor, how can wetlands improve water quality?","options":{"A":"They reduce the amount of rainfall","B":"They help filter water naturally","C":"They prevent all flooding in cities","D":"They make rivers flow more quickly"},"correct_answer":"B","explanation":"This is a detail question. The professor explains that wetland plants and soil can trap pollutants and nutrients, so wetlands help filter water naturally.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_43-46_aduaw8.mp3"},{"number":46,"recording_id":"C2","question":"Why does the professor mention plants, birds, fish, and insects?","options":{"A":"To explain why wetlands can support many species","B":"To show that wetlands are difficult to study","C":"To describe plants that cannot live in water","D":"To compare wetlands with forests"},"correct_answer":"A","explanation":"This is a purpose question. The professor mentions these living things to show that wetlands provide habitats for many species.\nRecording 3 — Script\nNarrator: Listen to a talk in an education class.\nProfessor: When many people think of libraries, they picture shelves of books and quiet reading rooms. Those are still part of many libraries, but the role of libraries has changed greatly over time.\nModern libraries often provide much more than printed books. Many offer access to online journals, electronic books, research databases, and digital archives. This is especially useful for students and researchers who need materials that may not be available in printed form.\nLibraries have also become places where people learn practical skills. For example, some libraries offer workshops on using computers, preparing résumés, or finding reliable information online. Others provide meeting rooms, language-learning materials, or programs for children and adults.\nThese changes do not mean that traditional books are no longer important. Instead, libraries have expanded their services. They continue to support reading, but they also help people find, evaluate, and use information in many different forms.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445373/Mock_Test_5_43-46_aduaw8.mp3"},{"number":47,"recording_id":"C3","question":"What is the talk mainly about?","options":{"A":"How public libraries began in ancient times","B":"Why some people prefer printed books","C":"How libraries have changed their services","D":"Why university libraries collect old books"},"correct_answer":"C","explanation":"This is a gist question. The professor explains how libraries have expanded beyond printed books and now offer many different services.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445371/Mock_Test_5_47-50_p3plzj.mp3"},{"number":48,"recording_id":"C3","question":"What does the professor say about modern libraries?","options":{"A":"They only lend books to students","B":"They provide access to digital resources","C":"They no longer need trained staff","D":"They focus mainly on rare collections"},"correct_answer":"B","explanation":"This is a detail question. The professor says modern libraries often provide access to online journals, electronic books, databases, and digital archives.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445371/Mock_Test_5_47-50_p3plzj.mp3"},{"number":49,"recording_id":"C3","question":"Why does the professor mention workshops on using computers and preparing résumés?","options":{"A":"To give an example of a modern library service","B":"To explain why books are expensive","C":"To show why libraries are becoming smaller","D":"To describe how computers are repaired"},"correct_answer":"A","explanation":"This is a purpose question. The professor gives these workshops as examples of modern library services beyond lending books.","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445371/Mock_Test_5_47-50_p3plzj.mp3"},{"number":50,"recording_id":"C3","question":"What can be inferred from the talk?","options":{"A":"Libraries are less useful than they were before","B":"Libraries have become places for many kinds of learning","C":"Libraries should stop lending printed materials","D":"Libraries are mainly important for historical research"},"correct_answer":"B","explanation":"This is an inference question. The professor says libraries now support reading, research, digital access, and practical learning, so libraries have become places for many kinds of learning.\nCopyable Transcript for ElevenLabs\nRecording 1\nListen to a lecture in a biology class.\nToday we’re going to discuss one way honeybees communicate with one another. When a worker bee finds a good source of nectar, it does not simply keep that information to itself. It returns to the hive and performs a special movement known as the waggle dance.\nThe waggle dance helps other bees know where food is located. The direction of the dance tells the other bees which way to fly in relation to the sun. The length of the dance gives information about distance. A longer dance usually means the food source is farther away.\nThis behavior is important because a colony has many bees, and they need to gather food efficiently. Instead of every bee searching randomly, successful bees can guide others to flowers that have already been found.\nScientists have studied this dance carefully because it shows that communication in animals does not always depend on sound. In the case of honeybees, movement can carry very specific information.\nWhat is the lecture mainly about?\nWhat information does the waggle dance provide?\nWhy does the professor mention the waggle dance?\nWhat can be inferred from the lecture?\nRecording 2\nListen to a lecture in an environmental science class.\nToday I want to talk about wetlands. A wetland is an area where water covers the soil, or is present near the surface, for at least part of the year. Wetlands are not exactly lakes, and they are not exactly dry land. They are areas where water and land conditions meet.\nWetlands are important for several reasons. First, they provide habitats for many plants, birds, fish, and insects. Some animals depend on wetlands for nesting or feeding, while others use them during migration.\nWetlands also help improve water quality. As water passes through a wetland, plants and soil can trap some pollutants and extra nutrients. In this way, wetlands act almost like natural filters.\nAnother important function of wetlands is flood control. During heavy rain, wetlands can hold extra water and release it slowly. This does not mean they prevent every flood, but they can reduce the impact of flooding in nearby areas.\nBecause of these benefits, many scientists and communities now work to protect wetlands that were once considered useless land.\nWhat is the lecture mainly about?\nWhat does the professor say about wetlands?\nAccording to the professor, how can wetlands improve water quality?\nWhy does the professor mention plants, birds, fish, and insects?\nRecording 3\nListen to a talk in an education class.\nWhen many people think of libraries, they picture shelves of books and quiet reading rooms. Those are still part of many libraries, but the role of libraries has changed greatly over time.\nModern libraries often provide much more than printed books. Many offer access to online journals, electronic books, research databases, and digital archives. This is especially useful for students and researchers who need materials that may not be available in printed form.\nLibraries have also become places where people learn practical skills. For example, some libraries offer workshops on using computers, preparing résumés, or finding reliable information online. Others provide meeting rooms, language-learning materials, or programs for children and adults.\nThese changes do not mean that traditional books are no longer important. Instead, libraries have expanded their services. They continue to support reading, but they also help people find, evaluate, and use information in many different forms.\nWhat is the talk mainly about?\nWhat does the professor say about modern libraries?\nWhy does the professor mention workshops on using computers and preparing résumés?\nWhat can be inferred from the talk?","audio_url":"https://res.cloudinary.com/english-tests-platform/video/upload/v1794445371/Mock_Test_5_47-50_p3plzj.mp3"}]}]},
  structure: {"title":"Structure and Written Expression","sections":[{"part":"A","title":"Structure","questions":[{"number":1,"stem":"The pattern of ridges on the fossil ______ that the animal lived in shallow water.","options":{"A":"suggesting","B":"which suggests","C":"suggests","D":"to suggest"},"correct_answer":"C","explanation":"Target: Finite main verb.\nThe singular subject pattern requires a finite predicate. Suggests supplies it; the following that-clause is its complement.\nCompleted sentence: The pattern of ridges on the fossil suggests that the animal lived in shallow water.\nOther options: A — Suggesting alone is non-finite. B — Which suggests creates a relative clause and leaves the sentence without a main predicate. D — To suggest is non-finite."},{"number":2,"stem":"The research team postponed ______ the telescope until the sky was clear.","options":{"A":"to adjust","B":"adjust","C":"adjusted","D":"adjusting"},"correct_answer":"D","explanation":"Target: Gerund complement.\nPostpone takes an -ing complement: postponed adjusting the telescope.\nCompleted sentence: The research team postponed adjusting the telescope until the sky was clear.\nOther options: A — Postpone does not take a to-infinitive in this construction. B — A bare infinitive cannot follow postponed here. C — The past form cannot function as the complement."},{"number":3,"stem":"______ the chamber had cooled, the technician removed the metal tray.","options":{"A":"After","B":"Following","C":"During","D":"Subsequent to"},"correct_answer":"A","explanation":"Target: Time clause connector.\nAfter introduces the finite clause the chamber had cooled.\nCompleted sentence: After the chamber had cooled, the technician removed the metal tray.\nOther options: B — Following does not directly introduce this bare finite clause. C — During requires a noun phrase rather than this clause. D — Subsequent to requires a nominal complement.\n\nStructure explanations 4 to 6"},{"number":4,"stem":"A narrow channel, ______, carries excess water away from the reservoir.","options":{"A":"it was built beneath the road","B":"built beneath the road","C":"was built beneath the road","D":"which building beneath the road"},"correct_answer":"B","explanation":"Target: Reduced passive relative clause.\nBuilt beneath the road is a passive participial modifier of channel. Carries is the main verb.\nCompleted sentence: A narrow channel, built beneath the road, carries excess water away from the reservoir.\nOther options: A — This inserts a separate independent clause between commas. C — The extra finite predicate lacks a relative connector. D — Which building lacks a finite verb and does not form a relative clause."},{"number":5,"stem":"The historian interviewed several residents ______ memories of the old harbour had never been recorded.","options":{"A":"whom","B":"who","C":"whose","D":"which"},"correct_answer":"C","explanation":"Target: Possessive relative connector.\nWhose modifies memories and expresses their relationship to the residents.\nCompleted sentence: The historian interviewed several residents whose memories of the old harbour had never been recorded.\nOther options: A — Whom is an object pronoun, not a possessive determiner. B — Who cannot modify memories to express possession. D — Which cannot express the required possession here."},{"number":6,"stem":"______ the movement of nearby stars requires observations made over many years.","options":{"A":"The tracking","B":"Tracking","C":"Tracked","D":"Tracks"},"correct_answer":"B","explanation":"Target: Gerund phrase as subject.\nTracking the movement of nearby stars is the subject of requires.\nCompleted sentence: Tracking the movement of nearby stars requires observations made over many years.\nOther options: A — The tracking would need of before the movement. C — Tracked cannot form this subject phrase. D — Tracks creates an ungrammatical sequence of finite verbs.\n\nStructure explanations 7 to 9"},{"number":7,"stem":"Not until the final layer of paint was removed ______ the original inscription.","options":{"A":"the restorers discovered","B":"the restorers did discover","C":"discovered the restorers","D":"did the restorers discover"},"correct_answer":"D","explanation":"Target: Inversion after not until.\nA fronted not until phrase requires subject–auxiliary inversion in the main clause: did the restorers discover.\nCompleted sentence: Not until the final layer of paint was removed did the restorers discover the original inscription.\nOther options: A — This uses ordinary statement order. B — The auxiliary remains after the subject. C — A lexical verb cannot be inverted this way; did is required."},{"number":8,"stem":"The report does not explain ______ the water level rose so quickly.","options":{"A":"why","B":"why did","C":"because of","D":"the reason of"},"correct_answer":"A","explanation":"Target: Embedded interrogative clause.\nWhy introduces an embedded question with statement order: the water level rose.\nCompleted sentence: The report does not explain why the water level rose so quickly.\nOther options: B — Why did the water level rose has both inappropriate inversion and a past verb after did. C — Because of cannot introduce the finite clause. D — The reason of cannot link directly to this clause."},{"number":9,"stem":"The lens is not large enough ______ the entire surface in a single image.","options":{"A":"capturing","B":"capture","C":"to capture","D":"for capture"},"correct_answer":"C","explanation":"Target: Enough and infinitive.\nThe pattern is adjective + enough + to-infinitive.\nCompleted sentence: The lens is not large enough to capture the entire surface in a single image.\nOther options: A — An -ing form does not complete this construction. B — The infinitive marker to is missing. D — For capture cannot take the entire surface as a direct object in this noun construction.\n\nStructure explanations 10 to 12"},{"number":10,"stem":"The archive contains several handwritten maps, ______ is more than two centuries old.","options":{"A":"each of them","B":"each of which","C":"which each","D":"and each which"},"correct_answer":"B","explanation":"Target: Relative clause with partitive phrase.\nEach of which is the singular subject of a relative clause referring to the maps.\nCompleted sentence: The archive contains several handwritten maps, each of which is more than two centuries old.\nOther options: A — Each of them would produce two independent clauses joined only by a comma. C — Which each reverses the required partitive structure and cannot serve as the subject here. D — Each which is not a grammatical noun phrase."},{"number":11,"stem":"______, the instrument can detect vibrations too weak for a person to feel.","options":{"A":"It is a highly sensitive device","B":"A highly sensitive device is","C":"Which is a highly sensitive device","D":"A highly sensitive device"},"correct_answer":"D","explanation":"Target: Appositive noun phrase.\nThe opening noun phrase renames the instrument; the following main clause is complete.\nCompleted sentence: A highly sensitive device, the instrument can detect vibrations too weak for a person to feel.\nOther options: A — This produces a comma splice. B — Is lacks its complement and disrupts the sentence. C — This relative clause has no preceding antecedent and cannot function as the appositive."},{"number":12,"stem":"______ the laboratory staff require assistance, a technician will be available by telephone.","options":{"A":"Should","B":"Had","C":"Were","D":"Do"},"correct_answer":"A","explanation":"Target: Inverted open condition.\nShould the laboratory staff require assistance means if the laboratory staff should require assistance.\nCompleted sentence: Should the laboratory staff require assistance, a technician will be available by telephone.\nOther options: B — Had would require a past participle rather than require. C — Were cannot be followed directly by the bare verb require in this construction. D — Do introduces a question, not the required conditional clause.\n\nStructure explanations 13 to 15"},{"number":13,"stem":"The survey recorded both the depth of the lake ______ the temperature of the water.","options":{"A":"also","B":"as well","C":"and","D":"but"},"correct_answer":"C","explanation":"Target: Correlative coordination.\nBoth pairs with and to join two noun phrases.\nCompleted sentence: The survey recorded both the depth of the lake and the temperature of the water.\nOther options: A — Both ... also is not the correlative construction. B — As well cannot link the two objects in this form. D — Both ... but is not the required pair."},{"number":14,"stem":"Although ______ carefully before transport, the glass vessels arrived with several cracks.","options":{"A":"they packing","B":"packed","C":"were packed","D":"packing them"},"correct_answer":"B","explanation":"Target: Reduced passive adverb clause.\nAlthough packed carefully before transport reduces although they were packed; the understood subject is the glass vessels.\nCompleted sentence: Although packed carefully before transport, the glass vessels arrived with several cracks.\nOther options: A — They packing lacks a finite auxiliary and cannot form a complete subordinate clause. C — A finite were packed clause needs an explicit subject. D — Packing them would make the vessels the implied packers and fails to give the intended passive relationship."},{"number":15,"stem":"The observation platform faces east, ______ visitors can watch the sunrise over the valley.","options":{"A":"because of","B":"in order to","C":"which","D":"so"},"correct_answer":"D","explanation":"Target: Coordinating result connector.\nSo connects the complete clauses and introduces the result.\nCompleted sentence: The observation platform faces east, so visitors can watch the sunrise over the valley.\nOther options: A — Because of cannot introduce a finite clause. B — In order to must be followed by a base verb, not visitors can watch. C — Which has no grammatical role in the following complete clause.\n\nWritten Expression explanations 16 to 20"}]},{"part":"B","title":"Written Expression","questions":[{"number":16,"underlined_text":"The collection of shells <u>from the offshore islands</u> <u>include</u> several species <u>that are rarely found</u> <u>near the mainland</u>.","options":{"A":"from the offshore islands","B":"include","C":"that are rarely found","D":"near the mainland"},"correct_answer":"B","explanation":"Correction: include → includes. Target: Subject verb agreement across modifiers.\nCollection is the singular head of the subject; the intervening plural nouns do not control the verb. A is a valid modifier of shells; C agrees with species; D is a valid location phrase.\nCorrected sentence: The collection of shells from the offshore islands includes several species that are rarely found near the mainland."},{"number":17,"underlined_text":"The <u>laboratory</u> has <u>recently</u> <u>began</u> a study of the effects of salt <u>on concrete</u>.","options":{"A":"laboratory","B":"recently","C":"began","D":"on concrete"},"correct_answer":"C","explanation":"Correction: began → begun. Target: Past participle after have.\nThe unmarked auxiliary has requires the past participle begun, not the simple past began. A names the subject; B is an appropriate adverb; D completes effects of salt on concrete.\nCorrected sentence: The laboratory has recently begun a study of the effects of salt on concrete."},{"number":18,"underlined_text":"Each applicant must submit two <u>photographs</u> and a <u>signed</u> form before the <u>office</u> can process the <u>apply</u>.","options":{"A":"photographs","B":"signed","C":"office","D":"apply"},"correct_answer":"D","explanation":"Correction: apply → application. Target: Noun form after article.\nThe article the requires a noun phrase here. Application is the object of process. A correctly follows two; B modifies form; C is the subject of can process.\nCorrected sentence: Each applicant must submit two photographs and a signed form before the office can process the application."},{"number":19,"underlined_text":"The surveyors recorded the position of each marker <u>accurate</u> <u>before</u> moving <u>the equipment</u> to <u>the next site</u>.","options":{"A":"accurate","B":"before","C":"the equipment","D":"the next site"},"correct_answer":"A","explanation":"Correction: accurate → accurately. Target: Adverb modifying a verb.\nAccurately describes how the surveyors recorded the positions and must be an adverb. B correctly introduces an -ing phrase; C is the object of moving; D is a valid destination phrase.\nCorrected sentence: The surveyors recorded the position of each marker accurately before moving the equipment to the next site."},{"number":20,"underlined_text":"Several pieces of <u>furniture</u> in the <u>western gallery</u> <u>requires</u> restoration because <u>their surfaces are damaged</u>.","options":{"A":"furniture","B":"western gallery","C":"requires","D":"their surfaces are damaged"},"correct_answer":"C","explanation":"Correction: requires → require. Target: Agreement with plural head noun.\nPieces, not furniture or gallery, is the plural head of the subject. It requires require. A is an uncountable noun after pieces of; B is a valid location phrase; D correctly refers to the plural pieces.\nCorrected sentence: Several pieces of furniture in the western gallery require restoration because their surfaces are damaged.\n\nWritten Expression explanations 21 to 25"},{"number":21,"underlined_text":"The new storage room is <u>more spacious</u> <u>than</u> the old one and contains <u>considerably</u> <u>less shelves</u>.","options":{"A":"more spacious","B":"than","C":"considerably","D":"less shelves"},"correct_answer":"D","explanation":"Correction: less shelves → fewer shelves. Target: Count noun quantifier.\nShelves are separate countable objects, so fewer is the standard quantifier in this comparison. A and B form a correct comparison; C modifies the degree of the difference.\nCorrected sentence: The new storage room is more spacious than the old one and contains considerably fewer shelves."},{"number":22,"underlined_text":"A safety officer should <u>examines</u> all climbing equipment <u>before</u> it is issued <u>to visitors</u> at <u>the entrance</u>.","options":{"A":"examines","B":"before","C":"to visitors","D":"the entrance"},"correct_answer":"A","explanation":"Correction: examines → examine. Target: Base verb after modal.\nShould requires the base form examine. The modal is outside the underline. B introduces the time clause; C marks the recipients; D is a valid location phrase.\nCorrected sentence: A safety officer should examine all climbing equipment before it is issued to visitors at the entrance."},{"number":23,"underlined_text":"The geologist <u>showed</u> the students a diagram and asked <u>their</u> to identify <u>the oldest layer</u> <u>of rock</u>.","options":{"A":"showed","B":"their","C":"the oldest layer","D":"of rock"},"correct_answer":"B","explanation":"Correction: their → them. Target: Object pronoun.\nAsked takes the object pronoun them before to identify. Their is a possessive determiner. A is a valid past-tense verb; C is the object of identify; D modifies layer.\nCorrected sentence: The geologist showed the students a diagram and asked them to identify the oldest layer of rock."},{"number":24,"underlined_text":"During the experiment, the liquid <u>gradually</u> became <u>cloudily</u> as tiny particles <u>formed</u> <u>near the bottom</u>.","options":{"A":"gradually","B":"cloudily","C":"formed","D":"near the bottom"},"correct_answer":"B","explanation":"Correction: cloudily → cloudy. Target: Adjective after linking verb.\nBecame requires an adjective describing the liquid. Cloudily is an adverb; cloudy describes its condition. A modifies became; C is the finite verb in the as-clause; D gives the location.\nCorrected sentence: During the experiment, the liquid gradually became cloudy as tiny particles formed near the bottom."},{"number":25,"underlined_text":"In the summer of 1996, the field team <u>collected</u> soil samples and <u>carefully</u> <u>has mapped</u> the boundaries of <u>the wetland</u>.","options":{"A":"collected","B":"carefully","C":"has mapped","D":"the wetland"},"correct_answer":"C","explanation":"Correction: has mapped → mapped. Target: Past tense in a finished period.\nThe explicitly finished period in 1996 requires simple past mapped, parallel with collected. A is correct simple past; B appropriately modifies the mapping action; D is a valid noun phrase.\nCorrected sentence: In the summer of 1996, the field team collected soil samples and carefully mapped the boundaries of the wetland.\n\nWritten Expression explanations 26 to 30"},{"number":26,"underlined_text":"The museum acquired <u>an</u> rare wooden mask <u>that had belonged</u> to a local family <u>for more than</u> <u>a century</u>.","options":{"A":"an","B":"that had belonged","C":"for more than","D":"a century"},"correct_answer":"A","explanation":"Correction: an → a. Target: Article before a consonant sound.\nRare begins with a consonant sound, so a is required. Rare itself is outside all underlines. B forms a complete relative clause; C introduces a duration; D correctly uses a before century.\nCorrected sentence: The museum acquired a rare wooden mask that had belonged to a local family for more than a century."},{"number":27,"underlined_text":"The revised programme allows volunteers <u>to register</u> online, <u>select</u> a work session, and <u>receive</u> confirmation <u>automatic</u>.","options":{"A":"to register","B":"select","C":"receive","D":"automatic"},"correct_answer":"D","explanation":"Correction: automatic → automatically. Target: Adverb modifying action.\nAutomatically modifies receive, explaining how confirmation is received. A, B, and C are parallel infinitive verbs sharing the initial to; confirmation is the object of receive.\nCorrected sentence: The revised programme allows volunteers to register online, select a work session, and receive confirmation automatically."},{"number":28,"underlined_text":"The labels on the bottles <u>were printed</u> in large letters so that workers could read <u>it</u> easily <u>under</u> <u>poor lighting conditions</u>.","options":{"A":"were printed","B":"it","C":"under","D":"poor lighting conditions"},"correct_answer":"B","explanation":"Correction: it → them. Target: Pronoun number agreement.\nThe object refers to the plural labels, so them is required. There is no singular referent for it. A is a correct plural passive; C is a valid preposition; D is its noun phrase complement.\nCorrected sentence: The labels on the bottles were printed in large letters so that workers could read them easily under poor lighting conditions."},{"number":29,"underlined_text":"The mechanical lift can raise heavy loads <u>safely</u> and <u>efficiently</u> without <u>damaging</u> <u>theirs contents</u>.","options":{"A":"safely","B":"efficiently","C":"damaging","D":"theirs contents"},"correct_answer":"D","explanation":"Correction: theirs contents → their contents. Target: Possessive determiner before noun.\nTheir modifies contents. The independent possessive pronoun theirs cannot precede the noun this way. A and B are parallel adverbs; C correctly follows without.\nCorrected sentence: The mechanical lift can raise heavy loads safely and efficiently without damaging their contents."},{"number":30,"underlined_text":"The walking route requires hikers to cross a stream, <u>climbing</u> a steep slope, and <u>follow</u> a narrow path <u>through</u> <u>the forest</u>.","options":{"A":"climbing","B":"follow","C":"through","D":"the forest"},"correct_answer":"A","explanation":"Correction: climbing → climb. Target: Parallel infinitives.\nThe three actions share to: to cross, climb, and follow. Climbing breaks that parallel construction. B is a base verb sharing to; C and D form a valid location phrase.\nCorrected sentence: The walking route requires hikers to cross a stream, climb a steep slope, and follow a narrow path through the forest.\n\nWritten Expression explanations 31 to 35"},{"number":31,"underlined_text":"The number of <u>proposals</u> <u>submitted yesterday</u> <u>exceed</u> the maximum permitted <u>under the current rules</u>.","options":{"A":"proposals","B":"submitted yesterday","C":"exceed","D":"under the current rules"},"correct_answer":"C","explanation":"Correction: exceed → exceeds. Target: Agreement with the number of.\nThe singular head number controls the verb. The plural proposals is inside the of-phrase, so exceeds is required. A is a plural noun after of; B is a reduced passive modifier of proposals; D is a valid prepositional phrase.\nCorrected sentence: The number of proposals submitted yesterday exceeds the maximum permitted under the current rules."},{"number":32,"underlined_text":"The old footbridge was <u>destroy</u> <u>by flooding</u> and was replaced <u>with</u> a steel structure <u>the following year</u>.","options":{"A":"destroy","B":"by flooding","C":"with","D":"the following year"},"correct_answer":"A","explanation":"Correction: destroy → destroyed. Target: Past participle in passive.\nWas requires the past participle destroyed in this passive construction. B identifies the cause; C correctly introduces the replacement; D is a time expression.\nCorrected sentence: The old footbridge was destroyed by flooding and was replaced with a steel structure the following year."},{"number":33,"underlined_text":"The researchers were <u>particularly</u> <u>interesting</u> in the unusual markings <u>on the leaves</u> <u>of the plant</u>.","options":{"A":"particularly","B":"interesting","C":"on the leaves","D":"of the plant"},"correct_answer":"B","explanation":"Correction: interesting → interested. Target: Participial adjective with in.\nPeople who experience interest are interested in something. Interesting describes something that causes interest. A modifies the adjective; C and D correctly identify the location and association of the markings.\nCorrected sentence: The researchers were particularly interested in the unusual markings on the leaves of the plant."},{"number":34,"underlined_text":"The measurements <u>obtained</u> with the new instrument are <u>more reliable</u> <u>than that</u> obtained with <u>the older model</u>.","options":{"A":"obtained","B":"more reliable","C":"than that","D":"the older model"},"correct_answer":"C","explanation":"Correction: than that → than those. Target: Plural comparative substitute.\nThose substitutes for plural measurements. Singular that cannot stand for this plural noun. A is a reduced passive modifier; B forms the comparison; D identifies the older instrument.\nCorrected sentence: The measurements obtained with the new instrument are more reliable than those obtained with the older model."},{"number":35,"underlined_text":"The committee will consider <u>the cost</u> of the repairs <u>as well as</u> their likely effect <u>on traffic</u> before <u>make</u> a decision.","options":{"A":"the cost","B":"as well as","C":"on traffic","D":"make"},"correct_answer":"D","explanation":"Correction: make → making. Target: Gerund after preposition.\nBefore takes an -ing form in this construction with no expressed subordinate subject. A is an object of consider; B links parallel noun phrases; C completes effect on traffic.\nCorrected sentence: The committee will consider the cost of the repairs as well as their likely effect on traffic before making a decision.\n\nWritten Expression explanations 36 to 40"},{"number":36,"underlined_text":"The greater the distance between the sensors, <u>the more difficult</u> it becomes <u>to detect</u> <u>small changes</u> <u>accurate</u>.","options":{"A":"the more difficult","B":"to detect","C":"small changes","D":"accurate"},"correct_answer":"D","explanation":"Correction: accurate → accurately. Target: Adverb in comparative construction.\nAccurately modifies detect and must be an adverb. The paired comparative the greater ... the more difficult is already correct. A completes the paired comparison; B is an infinitive complement; C is the object of detect.\nCorrected sentence: The greater the distance between the sensors, the more difficult it becomes to detect small changes accurately."},{"number":37,"underlined_text":"At the centre of the exhibition hall <u>stands</u> two sculptures <u>made</u> entirely <u>from recycled metal</u> <u>by local artists</u>.","options":{"A":"stands","B":"made","C":"from recycled metal","D":"by local artists"},"correct_answer":"A","explanation":"Correction: stands → stand. Target: Agreement with postposed subject.\nThe postposed subject is plural two sculptures. The verb must therefore be stand. B is a passive participial modifier; C gives the material; D identifies the makers.\nCorrected sentence: At the centre of the exhibition hall stand two sculptures made entirely from recycled metal by local artists."},{"number":38,"underlined_text":"The <u>final report</u> attributes the decline in crop yields <u>mainly</u> <u>for</u> a shortage of water <u>during the growing season</u>.","options":{"A":"final report","B":"mainly","C":"for","D":"during the growing season"},"correct_answer":"C","explanation":"Correction: for → to. Target: Attribute something to a cause.\nThe verb pattern is attribute an outcome to a cause. For cannot replace to in this construction. A is the subject noun phrase; B appropriately modifies the attribution; D is a valid time phrase.\nCorrected sentence: The final report attributes the decline in crop yields mainly to a shortage of water during the growing season."},{"number":39,"underlined_text":"The two routes differ <u>considerably</u> <u>in length</u>, but the <u>longer one</u> is more scenic <u>as</u> the shorter one.","options":{"A":"considerably","B":"in length","C":"longer one","D":"as"},"correct_answer":"D","explanation":"Correction: as → than. Target: Comparative connector.\nA comparative adjective uses than to introduce the second term of comparison. A is an adverb modifying differ; B is a correct complement; C refers to the longer of the two routes. The unmarked more scenic requires than.\nCorrected sentence: The two routes differ considerably in length, but the longer one is more scenic than the shorter one."},{"number":40,"underlined_text":"The <u>conservation team</u> succeeded <u>to restore</u> the faded lettering <u>without damaging</u> <u>the stone beneath it</u>.","options":{"A":"conservation team","B":"to restore","C":"without damaging","D":"the stone beneath it"},"correct_answer":"B","explanation":"Correction: to restore → in restoring. Target: Verb preposition gerund complement.\nSucceed takes in plus an -ing form: succeeded in restoring. A is the subject noun phrase; C correctly uses without plus an -ing form; D is the object of damaging and it refers to lettering.\nCorrected sentence: The conservation team succeeded in restoring the faded lettering without damaging the stone beneath it.\n\nProduction manifest and review notes"}]}]},
  reading: {"title":"Reading Comprehension","passages":[{"passage_number":1,"internal_topic":"Seed banks and living collections","paragraphs":[{"number":1,"text":"A packet of seeds may appear inactive, yet it can contain the starting material for a future population of plants. Seed banks preserve this possibility by keeping collections under conditions that extend their useful lives. The collections can support research, plant breeding, and the restoration of damaged vegetation. Unlike a collection of dried leaves displayed for identification, however, a seed bank must preserve living material. Its success depends on what the seeds can eventually do, rather than simply on how many packets fit on a shelf."},{"number":2,"text":"For many species, conventional storage involves reducing seed moisture and then keeping the seeds at low temperatures in sealed containers. These conditions slow deterioration, but the response varies among species. Some seeds cannot withstand drying, and others remain short-lived even in a conventional freezer. Researchers therefore investigate alternative methods, including the storage of specially prepared plant material at extremely low temperatures. The existence of these exceptions prevents a single storage procedure from serving every plant equally well."},{"number":3,"text":"The work begins before a collection enters a freezer. Collectors record where and when seeds were gathered and retain plant specimens that help confirm the species. They also leave sufficient seeds in the wild to allow the source population to reproduce. Each collection receives an identifying number linking it to the field records. This connection allows later users to trace the material's origin instead of treating every packet of the same species as interchangeable. Collecting from different populations can also help represent variation within a species."},{"number":4,"text":"Storage is followed by monitoring. Staff periodically remove samples and provide conditions suitable for germination, the beginning of growth from a seed. These tests show whether stored material still has the ability to produce seedlings. A disappointing result may prompt further investigation rather than the immediate disposal of a whole collection, since some seeds require particular treatments before they germinate. Maintaining a useful bank thus requires both suitable storage and knowledge of the plants being stored. Seed banking complements protection in the wild; preserving packets alone does not preserve the environments in which mature plants live."}],"full_text":"[1]  A packet of seeds may appear inactive, yet it can contain the starting material for a future population of plants. Seed banks preserve this possibility by keeping collections under conditions that extend their useful lives. The collections can support research, plant breeding, and the restoration of damaged vegetation. Unlike a collection of dried leaves displayed for identification, however, a seed bank must preserve living material. Its success depends on what the seeds can eventually do, rather than simply on how many packets fit on a shelf.\n\n[2]  For many species, conventional storage involves reducing seed moisture and then keeping the seeds at low temperatures in sealed containers. These conditions slow deterioration, but the response varies among species. Some seeds cannot withstand drying, and others remain short-lived even in a conventional freezer. Researchers therefore investigate alternative methods, including the storage of specially prepared plant material at extremely low temperatures. The existence of these exceptions prevents a single storage procedure from serving every plant equally well.\n\n[3]  The work begins before a collection enters a freezer. Collectors record where and when seeds were gathered and retain plant specimens that help confirm the species. They also leave sufficient seeds in the wild to allow the source population to reproduce. Each collection receives an identifying number linking it to the field records. This connection allows later users to trace the material's origin instead of treating every packet of the same species as interchangeable. Collecting from different populations can also help represent variation within a species.\n\n[4]  Storage is followed by monitoring. Staff periodically remove samples and provide conditions suitable for germination, the beginning of growth from a seed. These tests show whether stored material still has the ability to produce seedlings. A disappointing result may prompt further investigation rather than the immediate disposal of a whole collection, since some seeds require particular treatments before they germinate. Maintaining a useful bank thus requires both suitable storage and knowledge of the plants being stored. Seed banking complements protection in the wild; preserving packets alone does not preserve the environments in which mature plants live.","questions":[{"number":1,"question":"What is the passage mainly about?","options":{"A":"The use of dried leaves to identify unfamiliar plants","B":"The advantages of growing plants indoors throughout the year","C":"The work required to preserve useful seed collections","D":"The replacement of wild vegetation with cultivated plants"},"correct_answer":"C","explanation":"ITP1-R-S02-Q01  |  Main idea  |  Intended difficulty M\nEvidence: Whole passage.\nA: Dried leaves provide an opening comparison, not the main subject. B: Indoor cultivation is not the subject; stored seeds are not continuously grown. C: The text covers storage, collection records, monitoring, and limitations. D: Restoration is one use, but replacing wild vegetation is not advocated."},{"number":2,"question":"The word “extend” in paragraph 1 is closest in meaning to","options":{"A":"restore","B":"predict","C":"lengthen","D":"measure"},"correct_answer":"C","explanation":"ITP1-R-S02-Q02  |  Vocabulary  |  Intended difficulty E\nEvidence: Paragraph 1, sentence 2.\nA: The sentence concerns prolonging life, not bringing dead seeds back to life. B: Predicting a lifespan does not prolong it. C: Storage makes useful lives longer. D: No measurement is meant by this verb."},{"number":3,"question":"Why does the author compare a seed bank with a collection of dried leaves?","options":{"A":"To argue that plant identification is unnecessary for seed banking","B":"To emphasize that stored seeds must retain a biological capacity","C":"To explain why leaves occupy more storage space than seeds","D":"To suggest that seed banks should display their contents publicly"},"correct_answer":"B","explanation":"ITP1-R-S02-Q03  |  Author purpose  |  Intended difficulty H\nEvidence: Paragraph 1, final two sentences.\nA: Paragraph 3 explicitly describes confirming species identity. B: The comparison introduces the need to preserve living material capable of later growth. C: No comparison of physical size is made. D: Public display is not proposed."},{"number":4,"question":"According to paragraph 2, conventional storage for many species includes","options":{"A":"mixing seeds from several species in one container","B":"growing seedlings before placing them in sealed containers","C":"drying seeds before storing them in the cold","D":"keeping seeds moist while exposing them to light"},"correct_answer":"C","explanation":"ITP1-R-S02-Q04  |  Detail  |  Intended difficulty E\nEvidence: Paragraph 2, sentence 1.\nA: Mixing species is not described. B: The containers hold seeds, not growing seedlings. C: Reducing moisture precedes storage at low temperatures. D: The described method reduces moisture; light exposure is not specified."},{"number":5,"question":"The word “withstand” in paragraph 2 is closest in meaning to","options":{"A":"require","B":"accelerate","C":"reverse","D":"tolerate"},"correct_answer":"D","explanation":"ITP1-R-S02-Q05  |  Vocabulary  |  Intended difficulty M\nEvidence: Paragraph 2, sentence 3.\nA: The issue is inability to tolerate drying, not lack of a requirement. B: The seeds are not described as speeding up drying. C: Reversing drying is not the stated meaning. D: Some seeds cannot survive or tolerate drying.\n\nExplanations for Questions 6 to 10"},{"number":6,"question":"The phrase “This connection” in paragraph 3 refers to the link between","options":{"A":"different species and a shared storage container","B":"a numbered seed collection and its field records","C":"wild plants and the animals that spread their seeds","D":"dried leaves and the shelves on which they are displayed"},"correct_answer":"B","explanation":"ITP1-R-S02-Q06  |  Reference  |  Intended difficulty M\nEvidence: Paragraph 3, sentences 4–5.\nA: No common container for different species is described. B: The identifying number links each collection with its field information. C: Animal seed dispersal is not discussed. D: The display comparison is in paragraph 1 and is not this link."},{"number":7,"question":"All of the following are mentioned as part of collecting and documenting seeds EXCEPT","options":{"A":"measuring the height of every parent plant","B":"retaining specimens to help identify the species","C":"leaving seeds for the wild population to reproduce","D":"recording the place where seeds were gathered"},"correct_answer":"A","explanation":"ITP1-R-S02-Q07  |  Negative factual  |  Intended difficulty M\nEvidence: Paragraph 3; check the full passage for the exception.\nA: Measuring parent-plant height is not mentioned. B: Plant specimens help confirm species identity. C: Collectors leave sufficient seeds for reproduction. D: Collectors record where seeds were gathered."},{"number":8,"question":"According to paragraph 4, why are stored samples tested periodically?","options":{"A":"To determine how much space the containers occupy","B":"To establish the market price of each collection","C":"To check whether they can still produce seedlings","D":"To identify the animals present at the collection site"},"correct_answer":"C","explanation":"ITP1-R-S02-Q08  |  Detail  |  Intended difficulty E\nEvidence: Paragraph 4, sentences 2–3.\nA: Storage capacity is not the purpose of germination tests. B: No commercial valuation is described. C: The tests assess the continuing ability to produce seedlings. D: Animals at the site are not assessed."},{"number":9,"question":"What can be inferred about a sample that does not germinate during a test?","options":{"A":"Its identifying number must have been recorded incorrectly.","B":"Its failure may reflect unsuitable treatment rather than loss of life.","C":"Its source population is unlikely to reproduce in the wild.","D":"Its seeds should be stored together with unrelated species."},"correct_answer":"B","explanation":"ITP1-R-S02-Q09  |  Inference  |  Intended difficulty H\nEvidence: Paragraph 4, sentences 2–4.\nA: No necessary link to a recording error is given. B: Some seeds need particular treatments, so failure alone does not establish that they are dead. C: A storage test does not establish the wild population’s reproductive prospects. D: Mixing species is not proposed as a response."},{"number":10,"question":"The word “complements” in paragraph 4 is closest in meaning to","options":{"A":"supplements","B":"replaces","C":"duplicates","D":"delays"},"correct_answer":"A","explanation":"ITP1-R-S02-Q10  |  Vocabulary  |  Intended difficulty M\nEvidence: Paragraph 4, final sentence.\nA: Seed banking adds support to protection in the wild. B: Preserving packets alone does not preserve habitats. C: The two activities do not perform exactly the same task. D: No postponement of habitat protection is intended.\n\nExplanations for Questions 11 to 15"}]},{"passage_number":2,"internal_topic":"Urban heat and the interpretation of temperature","paragraphs":[{"number":1,"text":"On a clear evening, a built-up district may remain warm after nearby open land has cooled. This difference is one expression of an urban heat island: an area of development that is warmer than its surroundings. The effect does not require a large industrial city. It can arise wherever buildings and paved surfaces alter the exchange of heat with the environment. Nor is a city uniformly warm; a shaded park and a broad parking area can have quite different thermal conditions within the same neighborhood."},{"number":2,"text":"Several processes contribute to these contrasts. Many conventional roofs and pavements absorb solar energy during the day and release stored heat after sunset. Vegetation changes the balance by shading surfaces and releasing water vapor, a process that uses energy and can cool the surroundings. Where vegetation has been removed, both effects are reduced. Building arrangement matters as well: closely spaced structures can obstruct the wind that would otherwise carry heat away. Vehicles and equipment add heat, although they are not the sole cause of the phenomenon."},{"number":3,"text":"Measuring urban heat requires a distinction between surface temperature and air temperature. A sunlit roof can be much hotter than the air above it. Satellite instruments can estimate temperatures across extensive areas of roofs, roads, and vegetation, whereas instruments near the ground can record the temperature of the surrounding air. These measurements answer related but different questions. A map showing a very hot roof does not directly report the temperature experienced by someone standing in a shaded street below."},{"number":4,"text":"The timing of observations is equally important. A single afternoon image cannot reveal how quickly different districts cool overnight. Researchers therefore choose observation times and locations to match the question being investigated. The resulting evidence can guide changes such as adding shade or using roofing that reflects more sunlight. However, a lower roof temperature should not automatically be treated as an equal reduction in nearby air temperature. Evaluating a cooling measure means checking the outcome of interest, not merely selecting the most striking temperature change available."}],"full_text":"[1]  On a clear evening, a built-up district may remain warm after nearby open land has cooled. This difference is one expression of an urban heat island: an area of development that is warmer than its surroundings. The effect does not require a large industrial city. It can arise wherever buildings and paved surfaces alter the exchange of heat with the environment. Nor is a city uniformly warm; a shaded park and a broad parking area can have quite different thermal conditions within the same neighborhood.\n\n[2]  Several processes contribute to these contrasts. Many conventional roofs and pavements absorb solar energy during the day and release stored heat after sunset. Vegetation changes the balance by shading surfaces and releasing water vapor, a process that uses energy and can cool the surroundings. Where vegetation has been removed, both effects are reduced. Building arrangement matters as well: closely spaced structures can obstruct the wind that would otherwise carry heat away. Vehicles and equipment add heat, although they are not the sole cause of the phenomenon.\n\n[3]  Measuring urban heat requires a distinction between surface temperature and air temperature. A sunlit roof can be much hotter than the air above it. Satellite instruments can estimate temperatures across extensive areas of roofs, roads, and vegetation, whereas instruments near the ground can record the temperature of the surrounding air. These measurements answer related but different questions. A map showing a very hot roof does not directly report the temperature experienced by someone standing in a shaded street below.\n\n[4]  The timing of observations is equally important. A single afternoon image cannot reveal how quickly different districts cool overnight. Researchers therefore choose observation times and locations to match the question being investigated. The resulting evidence can guide changes such as adding shade or using roofing that reflects more sunlight. However, a lower roof temperature should not automatically be treated as an equal reduction in nearby air temperature. Evaluating a cooling measure means checking the outcome of interest, not merely selecting the most striking temperature change available.","questions":[{"number":11,"question":"Which statement best expresses the main idea of the passage?","options":{"A":"Heat in cities is produced mainly by traffic during the evening.","B":"Satellite maps provide a complete description of temperatures experienced by residents.","C":"Urban heat has several causes, and interpreting it requires careful measurement.","D":"Urban parks can prevent temperature differences from developing within cities."},"correct_answer":"C","explanation":"ITP1-R-S02-Q11  |  Main idea  |  Intended difficulty M\nEvidence: Whole passage.\nA: Traffic is one contributor, explicitly not the sole cause. B: The text distinguishes surface maps from experienced air temperatures. C: Paragraphs 1–2 explain causes and variation; paragraphs 3–4 explain measurement and interpretation. D: Parks can be cooler than nearby areas; they do not remove all contrasts."},{"number":12,"question":"The word “uniformly” in paragraph 1 is closest in meaning to","options":{"A":"unusually","B":"permanently","C":"gradually","D":"evenly"},"correct_answer":"D","explanation":"ITP1-R-S02-Q12  |  Vocabulary  |  Intended difficulty E\nEvidence: Paragraph 1, final sentence.\nA: It does not compare warmth with what is usual. B: The sentence concerns differences across places, not permanence. C: It does not describe a rate of change. D: The park and parking area show that heat is not distributed evenly."},{"number":13,"question":"According to paragraph 2, why may paved areas remain warm after sunset?","options":{"A":"They release heat that they absorbed earlier.","B":"They begin reflecting more sunlight at night.","C":"They draw water vapor from nearby vegetation.","D":"They increase the speed of winds between buildings."},"correct_answer":"A","explanation":"ITP1-R-S02-Q13  |  Detail  |  Intended difficulty E\nEvidence: Paragraph 2, sentence 2.\nA: Stored daytime energy is released after sunset. B: Sunlight reflection after sunset is not the explanation. C: Drawing vapor from plants is not described. D: Wind obstruction is associated with building arrangement, not this mechanism."},{"number":14,"question":"The phrase “both effects” in paragraph 2 refers to","options":{"A":"blocking wind and storing heat in equipment","B":"shading surfaces and releasing water vapor","C":"absorbing solar energy and producing vehicle heat","D":"cooling roofs and mapping nearby roads"},"correct_answer":"B","explanation":"ITP1-R-S02-Q14  |  Reference  |  Intended difficulty M\nEvidence: Paragraph 2, sentences 3–4.\nA: These are not the paired processes in the preceding sentence. B: The immediately preceding sentence names the two effects of vegetation. C: These are not the two vegetation processes. D: Mapping is introduced later and is not an effect of vegetation."},{"number":15,"question":"The word “obstruct” in paragraph 2 is closest in meaning to","options":{"A":"redirect","B":"measure","C":"block","D":"generate"},"correct_answer":"C","explanation":"ITP1-R-S02-Q15  |  Vocabulary  |  Intended difficulty M\nEvidence: Paragraph 2, sentence 5.\nA: A change of direction alone does not express the stated hindrance to airflow. B: Measurement is not the action of the buildings. C: Closely spaced structures impede the wind’s cooling movement. D: They do not create the wind in this statement.\n\nExplanations for Questions 16 to 20"},{"number":16,"question":"All of the following are mentioned as contributors to urban warmth EXCEPT","options":{"A":"heat released by vehicles and equipment","B":"the underground movement of hot water","C":"reduced vegetation cover","D":"the arrangement of buildings"},"correct_answer":"B","explanation":"ITP1-R-S02-Q16  |  Negative factual  |  Intended difficulty M\nEvidence: Paragraph 2; check the complete passage for the exception.\nA: Vehicles and equipment are explicitly mentioned. B: Underground hot water is not discussed. C: Removing vegetation reduces its cooling effects. D: Closely spaced structures can obstruct wind."},{"number":17,"question":"According to paragraph 3, what can satellite instruments estimate?","options":{"A":"The exact air temperature felt by each pedestrian","B":"Surface temperatures over large areas","C":"The overnight cooling rate from one afternoon image","D":"The temperature inside every building"},"correct_answer":"B","explanation":"ITP1-R-S02-Q17  |  Detail  |  Intended difficulty M\nEvidence: Paragraph 3, sentences 3–5.\nA: The text explicitly distinguishes the mapped roof temperature from street-level experience. B: They estimate temperatures across roofs, roads, and vegetation. C: Paragraph 4 says one image cannot reveal overnight cooling. D: Building interiors are not described as the satellite measurement."},{"number":18,"question":"The word “extensive” in paragraph 3 is closest in meaning to","options":{"A":"populated","B":"exposed","C":"distant","D":"large"},"correct_answer":"D","explanation":"ITP1-R-S02-Q18  |  Vocabulary  |  Intended difficulty E\nEvidence: Paragraph 3, sentence 3.\nA: Population is not what the adjective describes. B: Being uncovered does not express area size. C: Distance from the instrument is not its meaning here. D: The adjective describes the broad area covered."},{"number":19,"question":"What can be inferred about a comparison of two districts based only on an afternoon surface-temperature map?","options":{"A":"It can establish that both districts have the same air temperature.","B":"It will necessarily exaggerate the cooling effect of vegetation.","C":"It may not show which district retains more warmth during the night.","D":"It will be more useful if all ground instruments are removed."},"correct_answer":"C","explanation":"ITP1-R-S02-Q19  |  Inference  |  Intended difficulty H\nEvidence: Paragraph 4, sentences 1–3.\nA: Equal air temperatures cannot be established from the surface map. B: No inevitable direction of error is stated. C: The single image gives no overnight cooling pattern, so nighttime retention remains unresolved. D: The text favors measurement appropriate to the question, not removing instruments."},{"number":20,"question":"Why does the author mention a person in a shaded street in paragraph 3?","options":{"A":"To demonstrate that streets are warmer than roofs throughout the day","B":"To argue that satellite observations should be restricted to shaded areas","C":"To illustrate why a surface reading cannot directly represent a person’s air-temperature conditions","D":"To explain how pedestrians change the temperature of surrounding buildings"},"correct_answer":"C","explanation":"ITP1-R-S02-Q20  |  Author purpose  |  Intended difficulty H\nEvidence: Paragraph 3, final sentence.\nA: The passage gives no such comparison for the whole day. B: Restricting satellites to shade is not proposed. C: The example makes the surface–air distinction concrete. D: The person is a recipient of conditions, not a heat source in the example.\n\nExplanations for Questions 21 to 25"}]},{"passage_number":3,"internal_topic":"Pottery fragments as archaeological evidence","paragraphs":[{"number":1,"text":"An intact ancient bowl may attract more attention in a museum than a tray of broken pottery, but archaeologists do not judge evidence by completeness alone. Pottery fragments, often called sherds, retain information about the vessels from which they came. A small piece may preserve part of a painted design, the curve of a rim, or the materials mixed into the clay. Studied together, such fragments can help researchers investigate manufacture, the sequence of occupation at a site, and connections between communities."},{"number":2,"text":"Classification is usually an early step. Researchers compare attributes such as shape, surface treatment, and the composition of the pottery body. They may group fragments into types whose combinations of features recur across a collection. This procedure makes comparison manageable, but a type is an analytical category rather than the name of an individual potter. Two fragments with similar decoration need not have come from the same vessel. Likewise, counting fragments does not directly establish how many pots were used: one pot may break into many pieces."},{"number":3,"text":"Pottery can also contribute to dating. When a particular type has been associated with a known period elsewhere, its presence provides a clue to the age of a deposit. The position of the fragment matters. In an undisturbed sequence, deeper layers generally precede those above them. Later digging, however, can move an older fragment into a younger layer. Researchers must therefore examine how a deposit formed rather than assume that every object in it was made or discarded at the same time. A useful date depends on both the object and its setting."},{"number":4,"text":"Materials provide another line of inquiry. The clay and added particles in pottery can be compared with possible sources, helping researchers consider where a vessel was made. Finding nonlocal pottery may suggest movement or exchange, but it does not by itself identify the people who carried it or the route they followed. Decoration alone is also insufficient to prove that a vessel was imported, since a design can be copied. The strongest interpretations bring together several kinds of evidence while acknowledging what each leaves uncertain."}],"full_text":"[1]  An intact ancient bowl may attract more attention in a museum than a tray of broken pottery, but archaeologists do not judge evidence by completeness alone. Pottery fragments, often called sherds, retain information about the vessels from which they came. A small piece may preserve part of a painted design, the curve of a rim, or the materials mixed into the clay. Studied together, such fragments can help researchers investigate manufacture, the sequence of occupation at a site, and connections between communities.\n\n[2]  Classification is usually an early step. Researchers compare attributes such as shape, surface treatment, and the composition of the pottery body. They may group fragments into types whose combinations of features recur across a collection. This procedure makes comparison manageable, but a type is an analytical category rather than the name of an individual potter. Two fragments with similar decoration need not have come from the same vessel. Likewise, counting fragments does not directly establish how many pots were used: one pot may break into many pieces.\n\n[3]  Pottery can also contribute to dating. When a particular type has been associated with a known period elsewhere, its presence provides a clue to the age of a deposit. The position of the fragment matters. In an undisturbed sequence, deeper layers generally precede those above them. Later digging, however, can move an older fragment into a younger layer. Researchers must therefore examine how a deposit formed rather than assume that every object in it was made or discarded at the same time. A useful date depends on both the object and its setting.\n\n[4]  Materials provide another line of inquiry. The clay and added particles in pottery can be compared with possible sources, helping researchers consider where a vessel was made. Finding nonlocal pottery may suggest movement or exchange, but it does not by itself identify the people who carried it or the route they followed. Decoration alone is also insufficient to prove that a vessel was imported, since a design can be copied. The strongest interpretations bring together several kinds of evidence while acknowledging what each leaves uncertain.","questions":[{"number":21,"question":"What is the passage mainly about?","options":{"A":"Why pottery provides exact dates more reliably than other artifacts","B":"What pottery fragments can reveal and the care needed to interpret them","C":"How ancient potters selected decorations for individual customers","D":"Why museums prefer to display incomplete vessels rather than intact ones"},"correct_answer":"B","explanation":"ITP1-R-S02-Q21  |  Main idea  |  Intended difficulty M\nEvidence: Whole passage.\nA: No claim of exact dating superiority is made. B: The passage surveys classification, dating, and origins, with limits on interpretation. C: Customers’ choices are not discussed. D: The opening comparison does not establish a museum preference for fragments."},{"number":22,"question":"The word “retain” in paragraph 1 is closest in meaning to","options":{"A":"preserve","B":"require","C":"replace","D":"conceal"},"correct_answer":"A","explanation":"ITP1-R-S02-Q22  |  Vocabulary  |  Intended difficulty E\nEvidence: Paragraph 1, sentence 2.\nA: Fragments continue to hold information from the original vessels. B: Needing information is different from holding it. C: Fragments do not substitute new information for the old. D: The verb does not mean hiding the information."},{"number":23,"question":"According to paragraph 2, which feature may researchers use to classify pottery?","options":{"A":"The name of the person who excavated it","B":"The number of visitors who have examined it","C":"The treatment of its surface","D":"The modern price assigned to the vessel"},"correct_answer":"C","explanation":"ITP1-R-S02-Q23  |  Detail  |  Intended difficulty E\nEvidence: Paragraph 2, sentence 2.\nA: The excavator’s identity is not listed. B: Visitor numbers are not a classification attribute. C: Surface treatment is explicitly listed among the attributes. D: Market prices are not discussed."},{"number":24,"question":"The phrase “This procedure” in paragraph 2 refers to","options":{"A":"counting all the pots displayed in a museum","B":"reassembling each vessel before examining it","C":"grouping fragments by recurring combinations of features","D":"identifying the person who made each pot"},"correct_answer":"C","explanation":"ITP1-R-S02-Q24  |  Reference  |  Intended difficulty M\nEvidence: Paragraph 2, sentences 3–4.\nA: Museum pot counts are not the procedure described. B: Prior reassembly of every vessel is not required or stated. C: The phrase resumes the grouping into types described immediately before it. D: The text expressly distinguishes a type from a potter’s identity."},{"number":25,"question":"The word “establish” in paragraph 2 is closest in meaning to","options":{"A":"illustrate","B":"create","C":"increase","D":"determine"},"correct_answer":"D","explanation":"ITP1-R-S02-Q25  |  Vocabulary  |  Intended difficulty M\nEvidence: Paragraph 2, final sentence.\nA: The verb concerns demonstrating a number as known, not merely illustrating it. B: The counts do not create vessels. C: The question is knowing the number, not increasing it. D: Fragment counts cannot directly determine the number of pots.\n\nExplanations for Questions 26 to 30"},{"number":26,"question":"Suppose two deposits contain the same number of pottery fragments. What does paragraph 2 suggest?","options":{"A":"They must have been formed during the same period.","B":"They must include the same types of decoration.","C":"They could represent different numbers of original vessels.","D":"They probably contain pottery from a single maker."},"correct_answer":"C","explanation":"ITP1-R-S02-Q26  |  Inference  |  Intended difficulty H\nEvidence: Paragraph 2, final two sentences.\nA: The number of fragments does not establish a shared date. B: Equal counts provide no information about decoration. C: Different breakage patterns mean equal fragment totals need not imply equal vessel totals. D: A type does not identify a maker, and count does not do so either."},{"number":27,"question":"According to paragraph 3, how can later digging affect a deposit?","options":{"A":"It can place an older fragment in a more recent layer.","B":"It can change a fragment’s original painted design.","C":"It can establish the precise year a vessel was made.","D":"It can make all the deeper layers more recent than the upper ones."},"correct_answer":"A","explanation":"ITP1-R-S02-Q27  |  Detail  |  Intended difficulty M\nEvidence: Paragraph 3, sentences 4–6.\nA: Later disturbance can move older material into younger deposits. B: Changing decoration is not the effect described. C: Disturbance complicates rather than establishes precise dates. D: A possible local movement does not reverse the age of every layer."},{"number":28,"question":"The word “precede” in paragraph 3 is closest in meaning to","options":{"A":"cover","B":"come before","C":"resemble","D":"combine with"},"correct_answer":"B","explanation":"ITP1-R-S02-Q28  |  Vocabulary  |  Intended difficulty E\nEvidence: Paragraph 3, sentence 4.\nA: The deeper layers lie below; the verb expresses time order. B: Deeper undisturbed layers are earlier in the sequence. C: The statement concerns age, not resemblance. D: Combining layers is not meant."},{"number":29,"question":"All of the following are mentioned as cautions when interpreting pottery EXCEPT","options":{"A":"the possibility that museum lighting has altered a fragment’s color","B":"the possibility that potters copied a design from elsewhere","C":"the possibility that digging moved fragments between layers","D":"the possibility that one vessel produced many fragments"},"correct_answer":"A","explanation":"ITP1-R-S02-Q29  |  Negative factual  |  Intended difficulty H\nEvidence: Paragraphs 2–4; check the whole passage for the exception.\nA: Museum lighting and color alteration are not mentioned. B: Paragraph 4 says designs can be copied, limiting claims of importation. C: Paragraph 3 describes older fragments moving into younger layers. D: The final sentence of paragraph 2 gives this warning."},{"number":30,"question":"In which paragraph does the author explain why evidence of a vessel’s nonlocal origin does not establish its travel route?","options":{"A":"Paragraph 1","B":"Paragraph 2","C":"Paragraph 3","D":"Paragraph 4"},"correct_answer":"D","explanation":"ITP1-R-S02-Q30  |  Information location  |  Intended difficulty M\nEvidence: Paragraph 4, sentences 1–3.\nA: The introduction lists broad research uses without this distinction. B: Paragraph 2 discusses classification and counting. C: Paragraph 3 discusses age and disturbed layers. D: This paragraph distinguishes possible origin from carriers and routes.\n\nExplanations for Questions 31 to 35"}]},{"passage_number":4,"internal_topic":"Two early photographic processes","paragraphs":[{"number":1,"text":"Early photography did not develop around a single method of making pictures. Two influential nineteenth-century processes offered different possibilities: the daguerreotype, announced in 1839, and the paper-negative method developed by William Henry Fox Talbot. Both used light-sensitive materials to record an image, but the objects they produced were not equivalent. One yielded a unique picture on a metal plate; the other created an intermediate image from which additional prints could be made. This difference affected both the appearance of photographs and the ways they could circulate."},{"number":2,"text":"A daguerreotype carried its image on a highly polished, silver-coated copper plate. Its fine detail could be striking, but viewing the image depended on the angle at which light met the reflective surface. The delicate plate was commonly protected behind glass in a case. It was not a printing negative that could simply be placed against fresh paper to make another photograph. A photographer wishing to reproduce the picture could photograph the original, but that required a new camera exposure rather than another print from the same plate."},{"number":3,"text":"Talbot's calotype process instead produced a negative on chemically prepared paper. In this image, light and dark values were reversed relative to the subject. Placing the negative against another sheet of light-sensitive paper and exposing the pair to light produced a positive print. The negative could then be used again. These additional prints could be sent to different viewers without requiring the original subject to sit for another camera exposure. The paper fibers, however, could soften details in the finished photograph, making the result less sharply defined than a daguerreotype."},{"number":4,"text":"The comparison is therefore more complicated than a contest to make the clearest image. A viewer examining a small portrait might value minute detail, while someone seeking several copies of a view might value repeatable printing. The methods solved different practical problems, and the material supporting the image shaped the result. The negative-positive principle also separated the camera record from the photograph delivered to a viewer. That distinction made it possible for one recorded scene to reach multiple people as separate physical prints."}],"full_text":"[1]  Early photography did not develop around a single method of making pictures. Two influential nineteenth-century processes offered different possibilities: the daguerreotype, announced in 1839, and the paper-negative method developed by William Henry Fox Talbot. Both used light-sensitive materials to record an image, but the objects they produced were not equivalent. One yielded a unique picture on a metal plate; the other created an intermediate image from which additional prints could be made. This difference affected both the appearance of photographs and the ways they could circulate.\n\n[2]  A daguerreotype carried its image on a highly polished, silver-coated copper plate. Its fine detail could be striking, but viewing the image depended on the angle at which light met the reflective surface. The delicate plate was commonly protected behind glass in a case. It was not a printing negative that could simply be placed against fresh paper to make another photograph. A photographer wishing to reproduce the picture could photograph the original, but that required a new camera exposure rather than another print from the same plate.\n\n[3]  Talbot's calotype process instead produced a negative on chemically prepared paper. In this image, light and dark values were reversed relative to the subject. Placing the negative against another sheet of light-sensitive paper and exposing the pair to light produced a positive print. The negative could then be used again. These additional prints could be sent to different viewers without requiring the original subject to sit for another camera exposure. The paper fibers, however, could soften details in the finished photograph, making the result less sharply defined than a daguerreotype.\n\n[4]  The comparison is therefore more complicated than a contest to make the clearest image. A viewer examining a small portrait might value minute detail, while someone seeking several copies of a view might value repeatable printing. The methods solved different practical problems, and the material supporting the image shaped the result. The negative-positive principle also separated the camera record from the photograph delivered to a viewer. That distinction made it possible for one recorded scene to reach multiple people as separate physical prints.","questions":[{"number":31,"question":"What is the author’s primary purpose in the passage?","options":{"A":"To show that the first photographic method was superior in every respect","B":"To compare the practical and visual consequences of two early photographic methods","C":"To explain why nineteenth-century photographers stopped making portraits","D":"To describe the chemical preparation of every material used in photography"},"correct_answer":"B","explanation":"ITP1-R-S02-Q31  |  Main idea  |  Intended difficulty M\nEvidence: Whole passage.\nA: Each method has distinct advantages; universal superiority is not claimed. B: The discussion compares image detail, viewing, and reproduction in two processes. C: Portrait making is not said to have stopped. D: The passage gives an overview, not exhaustive chemical instructions."},{"number":32,"question":"The word “yielded” in paragraph 1 is closest in meaning to","options":{"A":"produced","B":"surrendered","C":"borrowed","D":"concealed"},"correct_answer":"A","explanation":"ITP1-R-S02-Q32  |  Vocabulary  |  Intended difficulty M\nEvidence: Paragraph 1, sentence 4.\nA: The process produced a picture. B: Giving way or surrendering is a different sense of the word. C: The image was created, not borrowed. D: The process made the image rather than hiding it."},{"number":33,"question":"According to paragraph 2, what affected the viewing of a daguerreotype?","options":{"A":"The thickness of fibers in the printing paper","B":"The distance the image had traveled from the photographer","C":"The number of prints previously made from its negative","D":"The angle of light striking its reflective surface"},"correct_answer":"D","explanation":"ITP1-R-S02-Q33  |  Detail  |  Intended difficulty E\nEvidence: Paragraph 2, sentence 2.\nA: Paper fibers concern the calotype process in paragraph 3. B: Travel distance is not identified as a viewing factor. C: A daguerreotype is not a reusable printing negative. D: The text directly states the importance of the lighting angle."},{"number":34,"question":"All of the following are mentioned as features of daguerreotypes EXCEPT","options":{"A":"a reusable negative made of paper","B":"a finely detailed image","C":"protection behind glass in a case","D":"a polished metal surface"},"correct_answer":"A","explanation":"ITP1-R-S02-Q34  |  Negative factual  |  Intended difficulty M\nEvidence: Paragraph 2.\nA: The paper negative belongs to Talbot’s process, not the daguerreotype. B: Fine detail is described in sentence 2. C: Glass and a case are mentioned in sentence 3. D: The silver-coated copper plate is highly polished."},{"number":35,"question":"The word “delicate” in paragraph 2 is closest in meaning to","options":{"A":"lightly colored","B":"carefully numbered","C":"recently invented","D":"easily damaged"},"correct_answer":"D","explanation":"ITP1-R-S02-Q35  |  Vocabulary  |  Intended difficulty E\nEvidence: Paragraph 2, sentence 3.\nA: Color is not the meaning here. B: Numbering is not discussed. C: The word describes fragility, not the date of invention. D: The need for protection supports vulnerability to damage.\n\nExplanations for Questions 36 to 40"},{"number":36,"question":"According to paragraph 3, how was a positive print made in Talbot’s process?","options":{"A":"By placing an untreated copper plate behind the finished photograph","B":"By taking a new camera exposure for every copy requested","C":"By removing all fibers from the paper after the image was formed","D":"By exposing light-sensitive paper in contact with the negative to light"},"correct_answer":"D","explanation":"ITP1-R-S02-Q36  |  Detail  |  Intended difficulty M\nEvidence: Paragraph 3, sentences 3–5.\nA: Copper plates belong to the other method; this procedure is not described. B: The negative can be reused without a new sitting or camera exposure. C: Fiber removal is not described. D: The negative and another sensitive sheet are placed together and exposed."},{"number":37,"question":"The phrase “These additional prints” in paragraph 3 refers to","options":{"A":"metal plates used to protect an original daguerreotype","B":"further positive images made from the same negative","C":"paper sheets prepared but not yet exposed to light","D":"new negatives made by photographing the same subject again"},"correct_answer":"B","explanation":"ITP1-R-S02-Q37  |  Reference  |  Intended difficulty M\nEvidence: Paragraph 3, sentences 3–5.\nA: The process uses paper, and plates are not the referent. B: The phrase refers to positives produced by reusing the negative. C: The prints already carry images; they are not unused sheets. D: The point is that another camera exposure is unnecessary."},{"number":38,"question":"The word “minute” in paragraph 4 is closest in meaning to","options":{"A":"very small","B":"quickly made","C":"widely known","D":"regularly repeated"},"correct_answer":"A","explanation":"ITP1-R-S02-Q38  |  Vocabulary  |  Intended difficulty E\nEvidence: Paragraph 4, sentence 2.\nA: Minute detail means extremely fine or small detail. B: The adjective does not express the time needed to make it. C: Fame is not the meaning. D: Repetition concerns copies, not the size of detail."},{"number":39,"question":"Why does the author contrast a portrait viewer with someone seeking several copies in paragraph 4?","options":{"A":"To show that the preferred method could depend on the intended use","B":"To explain why paper negatives were unsuitable for recording people","C":"To suggest that viewers generally disliked sharply defined photographs","D":"To establish that portraits were easier to reproduce than landscapes"},"correct_answer":"A","explanation":"ITP1-R-S02-Q39  |  Author purpose  |  Intended difficulty H\nEvidence: Paragraph 4, sentences 1–3.\nA: The contrasting priorities illustrate different practical advantages. B: The passage explicitly mentions a subject sitting for a camera exposure, and does not exclude people. C: The portrait viewer may value fine detail. D: Relative ease by subject type is not established."},{"number":40,"question":"What can be inferred about the value of the paper-negative method despite its softer detail?","options":{"A":"It allowed a positive print to be made without any exposure to light.","B":"It required viewers to examine the original negative together.","C":"It could be useful when distributing copies mattered more than maximum sharpness.","D":"It eliminated the need to protect photographic objects from damage."},"correct_answer":"C","explanation":"ITP1-R-S02-Q40  |  Inference  |  Intended difficulty H\nEvidence: Paragraph 3, final three sentences; paragraph 4.\nA: The positive-print process explicitly uses light. B: Separate prints can reach different viewers. C: Repeatable printing provides a benefit even when detail is less sharp. D: No general elimination of protection is claimed.\n\nExplanations for Questions 41 to 45"}]},{"passage_number":5,"internal_topic":"Carnegie libraries and continuing local support","paragraphs":[{"number":1,"text":"At the turn of the twentieth century, Andrew Carnegie's gifts helped communities build public libraries. His support reflected a belief that access to books could widen opportunities for people unable to purchase their own collections. As a young worker, he had benefited from borrowing books from a private library. His later giving helped expand free public provision, but a gift for a library building was not the same as a promise to meet every future expense. Communities accepting support also accepted responsibilities."},{"number":2,"text":"Under the widely used terms of the program, a community supplied a suitable site and committed itself to continuing financial support. Carnegie generally provided money for construction. Local authorities were expected to cover operating expenses, the recurring costs of running the library. These included such needs as staff and the care of the building. A common requirement was an annual commitment equal to ten percent of the construction grant. This amount represented a continuing obligation rather than a single additional payment made when the building opened."},{"number":3,"text":"The arrangement joined private generosity to public funding. A grant could remove a major initial obstacle, while the local commitment was intended to sustain the institution after construction ended. These obligations also meant that accepting a building involved a decision about future public spending. Residents were not simply being offered an object that would maintain itself. The distinction helps explain why the value of a grant cannot be assessed only by the size of the construction budget: a library's usefulness depends on services continuing inside the building."},{"number":4,"text":"Carnegie's interest in libraries extended beyond their appearance. He regarded them as opportunities for people to pursue knowledge through their own efforts. Nevertheless, the expansion of free library buildings should be distinguished from the claim that every resident actually received equal service. In the segregated United States, for example, racial barriers could restrict access even where a library was described as public. The buildings increased the capacity to provide books, but local policies and continuing support influenced how fully that capacity served the community."}],"full_text":"[1]  At the turn of the twentieth century, Andrew Carnegie's gifts helped communities build public libraries. His support reflected a belief that access to books could widen opportunities for people unable to purchase their own collections. As a young worker, he had benefited from borrowing books from a private library. His later giving helped expand free public provision, but a gift for a library building was not the same as a promise to meet every future expense. Communities accepting support also accepted responsibilities.\n\n[2]  Under the widely used terms of the program, a community supplied a suitable site and committed itself to continuing financial support. Carnegie generally provided money for construction. Local authorities were expected to cover operating expenses, the recurring costs of running the library. These included such needs as staff and the care of the building. A common requirement was an annual commitment equal to ten percent of the construction grant. This amount represented a continuing obligation rather than a single additional payment made when the building opened.\n\n[3]  The arrangement joined private generosity to public funding. A grant could remove a major initial obstacle, while the local commitment was intended to sustain the institution after construction ended. These obligations also meant that accepting a building involved a decision about future public spending. Residents were not simply being offered an object that would maintain itself. The distinction helps explain why the value of a grant cannot be assessed only by the size of the construction budget: a library's usefulness depends on services continuing inside the building.\n\n[4]  Carnegie's interest in libraries extended beyond their appearance. He regarded them as opportunities for people to pursue knowledge through their own efforts. Nevertheless, the expansion of free library buildings should be distinguished from the claim that every resident actually received equal service. In the segregated United States, for example, racial barriers could restrict access even where a library was described as public. The buildings increased the capacity to provide books, but local policies and continuing support influenced how fully that capacity served the community.","questions":[{"number":41,"question":"What is the passage mainly about?","options":{"A":"How Carnegie designed a single architectural style for every public library","B":"Why private book collections disappeared after public libraries were built","C":"Why construction costs became the main expense of libraries after they opened","D":"How Carnegie’s library gifts combined building support with continuing local responsibilities"},"correct_answer":"D","explanation":"ITP1-R-S02-Q41  |  Main idea  |  Intended difficulty H\nEvidence: Whole passage.\nA: A uniform architectural style is not described. B: No disappearance of private collections is claimed. C: The text emphasizes recurring expenses after construction, not continuing construction dominance. D: The text explains the division of support and how ongoing funding and policy affected service."},{"number":42,"question":"According to paragraph 1, what experience influenced Carnegie’s view of libraries?","options":{"A":"Managing a public library before entering industry","B":"Borrowing books while he was a young worker","C":"Selling books to finance his first business","D":"Designing a library building as a student"},"correct_answer":"B","explanation":"ITP1-R-S02-Q42  |  Detail  |  Intended difficulty E\nEvidence: Paragraph 1, sentences 2–3.\nA: Early library management is not mentioned. B: He benefited from access to a private library as a young worker. C: Book sales are not described. D: No architectural training or design experience is given."},{"number":43,"question":"The word “committed” in paragraph 2 is closest in meaning to","options":{"A":"limited","B":"introduced","C":"pledged","D":"compared"},"correct_answer":"C","explanation":"ITP1-R-S02-Q43  |  Vocabulary  |  Intended difficulty E\nEvidence: Paragraph 2, sentence 1.\nA: It undertook an obligation rather than limiting itself to no further support. B: Introducing oneself does not fit the financial obligation. C: The community pledged to provide continuing financial support. D: No comparison is expressed."},{"number":44,"question":"Which expression is explicitly defined in paragraph 2?","options":{"A":"construction grant","B":"suitable site","C":"local authorities","D":"operating expenses"},"correct_answer":"D","explanation":"ITP1-R-S02-Q44  |  Definition identification  |  Intended difficulty E\nEvidence: Paragraph 2, sentence 3.\nA: A grant is discussed, but this phrase is not explicitly defined. B: The site is required, but the phrase receives no definition. C: Authorities are mentioned as responsible parties without a definition. D: The phrase is immediately explained as the recurring costs of running the library."},{"number":45,"question":"According to paragraph 2, what was the purpose of the annual financial commitment?","options":{"A":"To repay the construction grant in one payment","B":"To purchase a new building site every year","C":"To transfer the library’s books to a private collection","D":"To provide recurring support after construction"},"correct_answer":"D","explanation":"ITP1-R-S02-Q45  |  Detail  |  Intended difficulty M\nEvidence: Paragraph 2, sentences 3–6.\nA: It is not a single payment or described as repayment. B: Only a suitable initial site is required. C: The public library is not described as transferring its books to private ownership. D: Operating costs recur, and the final sentence explicitly states continuing obligation.\n\nExplanations for Questions 46 to 50"},{"number":46,"question":"The phrase “These obligations” in paragraph 3 refers to","options":{"A":"the community’s commitments associated with accepting the building grant","B":"Carnegie’s childhood responsibilities as a young worker","C":"the demands made by publishers on private book buyers","D":"the duties of architects to reproduce a standard library design"},"correct_answer":"A","explanation":"ITP1-R-S02-Q46  |  Reference  |  Intended difficulty M\nEvidence: Paragraph 2 and paragraph 3, sentences 1–3.\nA: The phrase resumes local commitments, particularly continuing financial support. B: His childhood is background, not the referent of future public spending. C: Publisher demands are not discussed. D: No standard design obligation is described."},{"number":47,"question":"The word “sustain” in paragraph 3 is closest in meaning to","options":{"A":"enlarge","B":"maintain","C":"replace","D":"evaluate"},"correct_answer":"B","explanation":"ITP1-R-S02-Q47  |  Vocabulary  |  Intended difficulty M\nEvidence: Paragraph 3, sentence 2.\nA: Expansion is not required by the word. B: The local commitment keeps the institution functioning. C: The institution continues rather than being replaced. D: Assessment alone would not provide the continuing support meant here."},{"number":48,"question":"What can be inferred about two communities receiving construction grants of the same size?","options":{"A":"Their libraries could provide different levels of service after opening.","B":"Their residents would necessarily have equal access to the collections.","C":"They would be required to construct buildings with identical appearances.","D":"They would necessarily spend identical amounts on every future expense."},"correct_answer":"A","explanation":"ITP1-R-S02-Q48  |  Inference  |  Intended difficulty H\nEvidence: Paragraph 3, final sentence; paragraph 4, final two sentences.\nA: Usefulness depends on continuing services, and local support and policies influence access; equal construction grants do not fix these outcomes. B: The discussion of local access barriers rules out this necessary conclusion. C: No design uniformity is imposed. D: The text gives no requirement of identical future expenditure on every item."},{"number":49,"question":"According to paragraph 4, what could restrict access to a public library in the United States?","options":{"A":"The use of private money for the initial building","B":"Carnegie’s preference for lending only to young workers","C":"A shortage of construction sites in Europe","D":"Racial segregation"},"correct_answer":"D","explanation":"ITP1-R-S02-Q49  |  Detail  |  Intended difficulty M\nEvidence: Paragraph 4, sentence 4.\nA: Private construction funding is not stated to restrict access. B: His own experience does not become a lending restriction. C: European sites are not discussed. D: The passage explicitly names racial barriers in the segregated United States."},{"number":50,"question":"The word “capacity” in paragraph 4 is closest in meaning to","options":{"A":"popularity","B":"expense","C":"obligation","D":"ability"},"correct_answer":"D","explanation":"ITP1-R-S02-Q50  |  Vocabulary  |  Intended difficulty M\nEvidence: Paragraph 4, final sentence.\nA: Increased popularity is not the stated meaning. B: The word does not refer to cost. C: Capacity is what can be done, not a requirement to do it. D: Buildings increased the ability to provide books."}]}]}
};

export async function seedMockTest5(): Promise<{ success: boolean; testId: string; message: string }> {
  const data = mockTest5Data as any;
  const client = await getClient();
  try {
    await client.query('BEGIN');

    // 1. Check if Mock Test 5 already exists
    const existingTest = await client.query("SELECT id FROM tests WHERE title = 'Mock Test 5'");
    let testId: string;

    if (existingTest.rows.length > 0) {
      testId = existingTest.rows[0].id;
      // Clear old questions and sections
      const oldSections = await client.query('SELECT id FROM sections WHERE test_id = $1', [testId]);
      for (const s of oldSections.rows) {
        await client.query('DELETE FROM questions WHERE section_id = $1', [s.id]);
      }
      await client.query('DELETE FROM sections WHERE test_id = $1', [testId]);

      await client.query(`
        UPDATE tests 
        SET 
          description = 'Full-length TOEFL ITP mock test. Includes Listening Comprehension (50 questions), Structure & Written Expression (40 questions), and Reading Comprehension (50 questions).',
          is_published = false,
          is_free = false,
          duration_minutes = 115,
          updated_at = NOW()
        WHERE id = $1
      `, [testId]);
    } else {
      testId = uuidv4();
      const adminUser = await client.query("SELECT id FROM users WHERE role = 'admin' LIMIT 1");
      const createdBy = adminUser.rows.length > 0 ? adminUser.rows[0].id : null;

      await client.query(`
        INSERT INTO tests (id, title, description, test_type, is_published, is_free, duration_minutes, created_by, delivery_model, audio_thinking_time, created_at, updated_at)
        VALUES ($1, 'Mock Test 5', 'Full-length TOEFL ITP mock test. Includes Listening Comprehension (50 questions), Structure & Written Expression (40 questions), and Reading Comprehension (50 questions).', 'toefl_itp', false, false, 115, $2, 'legacy', 0, NOW(), NOW())
      `, [testId, createdBy]);
    }

    // --- 2. LISTENING SECTIONS ---
    // Section 1: Part A
    const partAQuestions = data.listening.parts[0].questions;
    const sec1Id = uuidv4();
    await client.query(`
      INSERT INTO sections (id, test_id, section_type, section_order, part_number, title, duration_minutes, instructions, audio_url, created_at, updated_at)
      VALUES ($1, $2, 'listening', 1, 1, 'Part A - Short Conversations', 17, 'In Part A, you will hear short conversations between two people. After each conversation, you will hear a question about the conversation. The conversations and questions will not be repeated. After you hear a question, read the four possible answers and choose the best answer.', null, NOW(), NOW())
    `, [sec1Id, testId]);

    for (const q of partAQuestions) {
      const qOptions = Object.entries(q.options).map(([k, text]) => ({ key: k, text }));
      await client.query(`
        INSERT INTO questions (id, section_id, question_number, question_type, question_text, question_data, correct_answer, points, explanation, audio_url, created_at, updated_at)
        VALUES ($1, $2, $3, 'multiple_choice', $4, $5, $6, 1, $7, $8, NOW(), NOW())
      `, [
        uuidv4(),
        sec1Id,
        q.number,
        q.question,
        JSON.stringify({
          part: 'A',
          options: qOptions,
          transcript: q.transcript
        }),
        JSON.stringify({ answer: q.correct_answer }),
        q.explanation,
        q.audio_url
      ]);
    }

    // Section 2 & 3: Part B
    const partBRecordings = data.listening.parts[1].recordings;
    const partBQuestions = data.listening.parts[1].questions;

    // Conv 1 (31-34)
    const sec2Id = uuidv4();
    await client.query(`
      INSERT INTO sections (id, test_id, section_type, section_order, part_number, title, duration_minutes, instructions, passage_text, audio_url, created_at, updated_at)
      VALUES ($1, $2, 'listening', 2, 2, 'Part B - Conversation 1', 4, 'In Part B, you will hear longer conversations. After each conversation, you will hear several questions. The conversations and questions will not be repeated. Choose the best answer to each question.', $3, $4, NOW(), NOW())
    `, [sec2Id, testId, partBRecordings[0].transcript, partBRecordings[0].audio_url]);

    for (const q of partBQuestions.filter((q: any) => q.recording_id === 'B1')) {
      const qOptions = Object.entries(q.options).map(([k, text]) => ({ key: k, text }));
      await client.query(`
        INSERT INTO questions (id, section_id, question_number, question_type, question_text, question_data, correct_answer, points, explanation, audio_url, group_label, created_at, updated_at)
        VALUES ($1, $2, $3, 'multiple_choice', $4, $5, $6, 1, $7, $8, 'Questions 31-34', NOW(), NOW())
      `, [
        uuidv4(),
        sec2Id,
        q.number,
        q.question,
        JSON.stringify({
          part: 'B',
          options: qOptions,
          recording_id: 'B1',
          transcript: partBRecordings[0].transcript
        }),
        JSON.stringify({ answer: q.correct_answer }),
        q.explanation,
        q.audio_url
      ]);
    }

    // Conv 2 (35-38)
    const sec3Id = uuidv4();
    await client.query(`
      INSERT INTO sections (id, test_id, section_type, section_order, part_number, title, duration_minutes, instructions, passage_text, audio_url, created_at, updated_at)
      VALUES ($1, $2, 'listening', 3, 2, 'Part B - Conversation 2', 4, 'In Part B, you will hear longer conversations. After each conversation, you will hear several questions. Choose the best answer to each question.', $3, $4, NOW(), NOW())
    `, [sec3Id, testId, partBRecordings[1].transcript, partBRecordings[1].audio_url]);

    for (const q of partBQuestions.filter((q: any) => q.recording_id === 'B2')) {
      const qOptions = Object.entries(q.options).map(([k, text]) => ({ key: k, text }));
      await client.query(`
        INSERT INTO questions (id, section_id, question_number, question_type, question_text, question_data, correct_answer, points, explanation, audio_url, group_label, created_at, updated_at)
        VALUES ($1, $2, $3, 'multiple_choice', $4, $5, $6, 1, $7, $8, 'Questions 35-38', NOW(), NOW())
      `, [
        uuidv4(),
        sec3Id,
        q.number,
        q.question,
        JSON.stringify({
          part: 'B',
          options: qOptions,
          recording_id: 'B2',
          transcript: partBRecordings[1].transcript
        }),
        JSON.stringify({ answer: q.correct_answer }),
        q.explanation,
        q.audio_url
      ]);
    }

    // Section 4, 5, 6: Part C
    const partCRecordings = data.listening.parts[2].recordings;
    const partCQuestions = data.listening.parts[2].questions;

    const talkConfigs = [
      { id: 'C1', order: 4, title: 'Part C - Talk 1', duration: 3, recIdx: 0, group: 'Questions 39-42' },
      { id: 'C2', order: 5, title: 'Part C - Talk 2', duration: 3, recIdx: 1, group: 'Questions 43-46' },
      { id: 'C3', order: 6, title: 'Part C - Talk 3', duration: 4, recIdx: 2, group: 'Questions 47-50' }
    ];

    for (const tc of talkConfigs) {
      const secId = uuidv4();
      const rec = partCRecordings[tc.recIdx];
      await client.query(`
        INSERT INTO sections (id, test_id, section_type, section_order, part_number, title, duration_minutes, instructions, passage_text, audio_url, created_at, updated_at)
        VALUES ($1, $2, 'listening', $3, 3, $4, $5, 'In Part C, you will hear several short talks. After each talk, you will hear some questions. Choose the best answer to each question.', $6, $7, NOW(), NOW())
      `, [secId, testId, tc.order, tc.title, tc.duration, rec.transcript, rec.audio_url]);

      for (const q of partCQuestions.filter((q: any) => q.recording_id === tc.id)) {
        const qOptions = Object.entries(q.options).map(([k, text]) => ({ key: k, text }));
        await client.query(`
          INSERT INTO questions (id, section_id, question_number, question_type, question_text, question_data, correct_answer, points, explanation, audio_url, group_label, created_at, updated_at)
          VALUES ($1, $2, $3, 'multiple_choice', $4, $5, $6, 1, $7, $8, $9, NOW(), NOW())
        `, [
          uuidv4(),
          secId,
          q.number,
          q.question,
          JSON.stringify({
            part: 'C',
            options: qOptions,
            recording_id: tc.id,
            transcript: rec.transcript
          }),
          JSON.stringify({ answer: q.correct_answer }),
          q.explanation,
          rec.audio_url,
          tc.group
        ]);
      }
    }

    // --- 3. STRUCTURE AND WRITTEN EXPRESSION ---
    const sec7Id = uuidv4();
    await client.query(`
      INSERT INTO sections (id, test_id, section_type, section_order, part_number, title, duration_minutes, instructions, created_at, updated_at)
      VALUES ($1, $2, 'structure', 7, null, 'Structure and Written Expression', 25, 'This section is designed to measure your ability to recognize language that is appropriate for standard written English. Questions 1–15 are incomplete sentences. Beneath each sentence you will see four words or phrases, marked (A), (B), (C), and (D). Choose the one word or phrase that best completes the sentence.\n\nQuestions 16–40 have four underlined words or phrases. The four underlined parts of the sentence are marked (A), (B), (C), and (D). Identify the one underlined word or phrase that must be changed in order for the sentence to be correct.', NOW(), NOW())
    `, [sec7Id, testId]);

    // Structure 1-15
    for (const q of data.structure.sections[0].questions) {
      const qOptions = Object.entries(q.options).map(([k, text]) => ({ key: k, text }));
      await client.query(`
        INSERT INTO questions (id, section_id, question_number, question_type, question_text, question_data, correct_answer, points, explanation, created_at, updated_at)
        VALUES ($1, $2, $3, 'multiple_choice', $4, $5, $6, 1, $7, NOW(), NOW())
      `, [
        uuidv4(),
        sec7Id,
        q.number,
        q.stem,
        JSON.stringify({
          part: 'A',
          options: qOptions
        }),
        JSON.stringify({ answer: q.correct_answer }),
        q.explanation
      ]);
    }

    // Written Expression 16-40
    for (const q of data.structure.sections[1].questions) {
      const qOptions = Object.entries(q.options).map(([k, text]) => ({ key: k, text }));
      await client.query(`
        INSERT INTO questions (id, section_id, question_number, question_type, question_text, question_data, correct_answer, points, explanation, created_at, updated_at)
        VALUES ($1, $2, $3, 'multiple_choice', $4, $5, $6, 1, $7, NOW(), NOW())
      `, [
        uuidv4(),
        sec7Id,
        q.number,
        q.underlined_text,
        JSON.stringify({
          part: 'B',
          options: qOptions
        }),
        JSON.stringify({ answer: q.correct_answer }),
        q.explanation
      ]);
    }

    // --- 4. READING PASSAGES ---
    for (let pIdx = 0; pIdx < data.reading.passages.length; pIdx++) {
      const passage = data.reading.passages[pIdx];
      const secOrder = 8 + pIdx;
      const secTitle = `Reading Passage ${pIdx + 1}`;
      const secId = uuidv4();
      const groupLabel = `Questions ${pIdx * 10 + 1}-${pIdx * 10 + 10}`;

      await client.query(`
        INSERT INTO sections (id, test_id, section_type, section_order, part_number, title, duration_minutes, instructions, passage_title, passage_text, created_at, updated_at)
        VALUES ($1, $2, 'reading', $3, null, $4, 11, 'Directions: In this section you will read several passages. Each one is followed by a number of questions about it. You are to choose the one best answer, (A), (B), (C), or (D), to each question.', $5, $6, NOW(), NOW())
      `, [secId, testId, secOrder, secTitle, passage.internal_topic, passage.full_text]);

      for (const q of passage.questions) {
        const qOptions = Object.entries(q.options).map(([k, text]) => ({ key: k, text }));

        await client.query(`
          INSERT INTO questions (id, section_id, question_number, question_type, question_text, question_data, correct_answer, points, explanation, group_label, created_at, updated_at)
          VALUES ($1, $2, $3, 'multiple_choice', $4, $5, $6, 1, $7, $8, NOW(), NOW())
        `, [
          uuidv4(),
          secId,
          q.number,
          q.question,
          JSON.stringify({
            options: qOptions
          }),
          JSON.stringify({ answer: q.correct_answer }),
          q.explanation,
          groupLabel
        ]);
      }
    }

    await client.query('COMMIT');
    return {
      success: true,
      testId,
      message: 'Successfully seeded Mock Test 5 into database (unpublished status).'
    };
  } catch (err: any) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
